pub(crate) fn pc_f_r(f0: &mut crate::port::Cells, f1: &mut crate::port::Cells, f2: &mut crate::port::Cells, f3: &mut crate::port::Cells, slot: i32, which: i32) -> i32 {
    // A font's descriptor facts for the `fonts` row: which 0 subtype, 1 /Flags, 2 has a ToUnicode,
    // 3 base encoding, 4 kind (1 simple).
    if slot == 0 {
        if which == 0 {
            return pfn_subtype(f0);
        }
        if which == 1 {
            return pfn_flags(f0);
        }
        if which == 2 {
            return pfn_has_tounicode(f0);
        }
        if which == 3 {
            return pfn_encoding(f0);
        }
        return pfn_kind_of(f0);
    }
    if slot == 1 {
        if which == 0 {
            return pfn_subtype(f1);
        }
        if which == 1 {
            return pfn_flags(f1);
        }
        if which == 2 {
            return pfn_has_tounicode(f1);
        }
        if which == 3 {
            return pfn_encoding(f1);
        }
        return pfn_kind_of(f1);
    }
    if slot == 2 {
        if which == 0 {
            return pfn_subtype(f2);
        }
        if which == 1 {
            return pfn_flags(f2);
        }
        if which == 2 {
            return pfn_has_tounicode(f2);
        }
        if which == 3 {
            return pfn_encoding(f2);
        }
        return pfn_kind_of(f2);
    }
    if which == 0 {
        return pfn_subtype(f3);
    }
    if which == 1 {
        return pfn_flags(f3);
    }
    if which == 2 {
        return pfn_has_tounicode(f3);
    }
    if which == 3 {
        return pfn_encoding(f3);
    }
    return pfn_kind_of(f3);
}
pub(crate) fn pc_name_find(ar: &mut crate::port::Cells, nh: i32, n: i32, c0: i32, c1: i32, c2: i32, c3: i32, c4: i32, c5: i32, c6: i32) -> i32 {
    // 1 when the name nh contains the n (1..7) characters c0.. in a row.
    let ln: i32 = pl_name_len(ar, nh);
    let mut i: i32 = 0;
    let mut ok: i32 = 1;
    while (i + n) <= ln {
        ok = 1;
        if pl_name_byte(ar, nh, i) != c0 {
            ok = 0;
        }
        if (n > 1) && (pl_name_byte(ar, nh, i + 1) != c1) {
            ok = 0;
        }
        if (n > 2) && (pl_name_byte(ar, nh, i + 2) != c2) {
            ok = 0;
        }
        if (n > 3) && (pl_name_byte(ar, nh, i + 3) != c3) {
            ok = 0;
        }
        if (n > 4) && (pl_name_byte(ar, nh, i + 4) != c4) {
            ok = 0;
        }
        if (n > 5) && (pl_name_byte(ar, nh, i + 5) != c5) {
            ok = 0;
        }
        if (n > 6) && (pl_name_byte(ar, nh, i + 6) != c6) {
            ok = 0;
        }
        if ok == 1 {
            return 1;
        }
        i += 1;
    }
    return 0;
}
pub(crate) fn pc_font_row(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut fnt: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, slot: i32, status: i32, key: i32) -> i32 {
    // The `fonts` row of a font the document shows for the first time (its row is its id): object
    // number, subtype, /Flags, whether it has a ToUnicode, base encoding, /BaseFont, ascent, descent,
    // the width of a space (simple fonts), and a style from the flags and the name. P1.6 reads no
    // font programs, /ItalicAngle or /StemV (`pdfnames` has no such names): program 0, italic angle 0,
    // stem -1. A font that would not load has subtype 0 and no metrics.
    let row: i32 = fo_new(fnt, crate::port::cells_at(cx, C_CUR + G_FOBJ), 0);
    let nh: i32 = pd_dget(src, ar, dc, a, b, st, key, pn_base_font());
    let mut flags: i32 = 0;
    let mut sty: i32 = 0;
    let mut i: i32 = 0;
    let mut start: i32 = 0;
    let mut ln: i32 = 0;
    if status == 0 {
        fo_set(fnt, row, fnf_subtype(), pc_f_r(f0, f1, f2, f3, slot, 0));
        flags = pc_f_r(f0, f1, f2, f3, slot, 1);
        fo_set(fnt, row, fnf_flags(), flags);
        fo_set(fnt, row, fnf_tounicode(), pc_f_r(f0, f1, f2, f3, slot, 2));
        fo_set(fnt, row, fnf_enc(), pc_f_r(f0, f1, f2, f3, slot, 3));
        fo_set(fnt, row, fnf_asc(), pc_f_q(f0, f1, f2, f3, slot, 0));
        fo_set(fnt, row, fnf_desc(), pc_f_q(f0, f1, f2, f3, slot, 1));
        if pc_f_r(f0, f1, f2, f3, slot, 4) == 1 {
            fo_set(fnt, row, fnf_space(), pc_f_width(f0, f1, f2, f3, slot, 32));
        }
    }
    if (nh != 0) && (pl_kind_of(ar, nh) == 4) {
        ln = pl_name_len(ar, nh);
        start = crate::port::cells_len(et);
        while i < ln {
            etx_append_cp(et, pl_name_byte(ar, nh, i));
            i += 1;
        }
        fo_set(fnt, row, fnf_tstart(), start);
        fo_set(fnt, row, fnf_tlen(), ln);
        if pc_name_find(ar, nh, 4, 66, 111, 108, 100, 0, 0, 0) == 1 {
            sty |= sy_bold();
        }
        if pc_name_find(ar, nh, 6, 73, 116, 97, 108, 105, 99, 0) == 1 {
            sty |= sy_italic();
        }
        if pc_name_find(ar, nh, 7, 79, 98, 108, 105, 113, 117, 101) == 1 {
            sty |= sy_italic();
        }
    }
    if (flags & 1) != 0 {
        sty |= sy_mono();
    }
    if (flags & 64) != 0 {
        sty |= sy_italic();
    }
    if (flags & 131072) != 0 {
        sty |= sy_smallcaps();
    }
    if (flags & 262144) != 0 {
        sty |= sy_bold();
    }
    fo_set(fnt, row, fnf_style(), sty);
    return row;
}
pub(crate) fn pc_font_id(mut cx: &mut crate::port::Cells, key: i32) -> i32 {
    // The evidence id of a font dictionary: its index in the order the
    // document first showed it. THE BUDGET `fonts-per-doc` (kind 14, at most MAX_FIDS = 512): the font past it has no id, -1, which is the
    // evidence's 'no font' (its glyphs carry -1 and it has no `fonts` row); the text is still read in the font's own encoding, and the page
    // that shows it is flagged (W_FONTS). The same on every host, since the decision is made here.
    let n: i32 = crate::port::cells_at(cx, C_NFONT);
    let mut i: i32 = 0;
    while i < n {
        if crate::port::cells_at(cx, C_FIDS + i) == key {
            return i;
        }
        i += 1;
    }
    if n >= crate::port::cells_at(cx, C_FIDLIM) {
        return -1;
    }
    crate::port::cells_set(cx, C_FIDS + n, key);
    crate::port::cells_set(cx, C_NFONT, n + 1);
    return n;
}
pub(crate) fn pc_ensure_font(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, mut fnt: &mut crate::port::Cells, mut et: &mut crate::port::Cells) -> i32 {
    // Make the current font (the graphics state's) resident in a slot and set
    // C_SLOT to it, -1 when there is none. A font is loaded once and kept; the
    // slot that has gone unused longest is the one replaced.
    let key: i32 = crate::port::cells_at(cx, C_CUR + G_FONT);
    let mut i: i32 = 0;
    let mut at: i32 = 0;
    let mut pick: i32 = 0;
    let mut best: i32 = 2147483647;
    let mut status: i32 = 0;
    let mut fid: i32 = 0;
    let nbefore: i32 = crate::port::cells_at(cx, C_NFONT);
    let mut clock: i32 = crate::port::cells_at(cx, C_CLOCK);
    if key == 0 {
        crate::port::cells_set(cx, C_SLOT, -1);
        return 0;
    }
    clock += 1;
    crate::port::cells_set(cx, C_CLOCK, clock);
    while i < 4 {
        at = C_SLOTS + (i * SLOT_STRIDE);
        if crate::port::cells_at(cx, at + S_KEY) == key {
            crate::port::cells_set(cx, at + S_USE, clock);
            crate::port::cells_set(cx, C_SLOT, i);
            return 0;
        }
        if crate::port::cells_at(cx, at + S_USE) < best {
            best = crate::port::cells_at(cx, at + S_USE);
            pick = i;
        }
        i += 1;
    }
    at = C_SLOTS + (pick * SLOT_STRIDE);
    status = pc_f_load(src, ar, dc, a, b, st, out, f0, f1, f2, f3, pick, key);
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
        crate::port::cells_set(cx, at + S_KEY, 0);
        crate::port::cells_set(cx, C_SLOT, -1);
        return 0;
    }
    crate::port::cells_set(cx, at + S_KEY, key);
    crate::port::cells_set(cx, at + S_USE, clock);
    crate::port::cells_set(cx, at + S_STATUS, status);
    fid = pc_font_id(cx, key);
    crate::port::cells_set(cx, at + S_ID, fid);
    // A font the document has not shown before gets its `fonts` row, which is its id.
    if (fid >= 0) && (fid == nbefore) {
        pc_font_row(src, ar, dc, a, b, st, cx, fnt, et, f0, f1, f2, f3, pick, status, key);
    }
    if status == 0 {
        crate::port::cells_set(cx, at + S_ASC, pc_f_q(f0, f1, f2, f3, pick, 0));
        crate::port::cells_set(cx, at + S_DESC, pc_f_q(f0, f1, f2, f3, pick, 1));
        crate::port::cells_set(cx, at + S_VERT, pc_f_q(f0, f1, f2, f3, pick, 2));
        crate::port::cells_set(cx, at + S_DW2V, pc_f_q(f0, f1, f2, f3, pick, 3));
        crate::port::cells_set(cx, at + S_DW2W, pc_f_q(f0, f1, f2, f3, pick, 4));
    } else {
        crate::port::cells_set(cx, at + S_ASC, 0);
        crate::port::cells_set(cx, at + S_DESC, 0);
        crate::port::cells_set(cx, at + S_VERT, 0);
    }
    crate::port::cells_set(cx, C_SLOT, pick);
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
    }
    return 0;
}
pub(crate) fn pc_tf(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, ox: &mut crate::port::Cells, n: i32) -> i32 {
    // Tf: the font named by operand 0 from the current Resources, at the size of
    // operand 1. The dictionary is resolved here and loaded at the first glyph.
    let size: i64 = pc_num(ox, n, 1);
    let mut fh: i32 = 0;
    let mut raw: i32 = 0;
    fx_put(cx, C_CUR + G_FS, size);
    if (n >= 1) && (pc_kind(ox, 0) == K_NAME) {
        raw = pc_res_entry(src, ar, dc, a, b, st, cx, ox, pn_font(), 0);
        if raw != 0 {
            fh = pd_resolve(src, ar, dc, a, b, st, raw);
        }
    }
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
        return 0;
    }
    if fh == 0 {
        pc_warn_set(cx, W_FONT);
    } else if pl_kind_of(ar, fh) != 7 {
        fh = 0;
        pc_warn_set(cx, W_FONT);
    }
    crate::port::cells_set(cx, C_CUR + G_FONT, fh);
    crate::port::cells_set(cx, C_CUR + G_FOBJ, 0);
    if (fh != 0) && (raw != 0) {
        if pl_kind_of(ar, raw) == 9 {
            crate::port::cells_set(cx, C_CUR + G_FOBJ, pl_int_value(ar, raw));
        }
    }
    return 0;
}
pub(crate) fn pc_min4(p: i64, q: i64, r: i64, s: i64) -> i64 {
    let mut m: i64 = p;
    if q < m {
        m = q;
    }
    if r < m {
        m = r;
    }
    if s < m {
        m = s;
    }
    return m;
}
pub(crate) fn pc_max4(p: i64, q: i64, r: i64, s: i64) -> i64 {
    let mut m: i64 = p;
    if q > m {
        m = q;
    }
    if r > m {
        m = r;
    }
    if s > m {
        m = s;
    }
    return m;
}
pub(crate) fn pc_dir_angle(a: i64, b: i64) -> i32 {
    // The angle of the direction (a, b) in page space (y down), by `ev-angle`: halve both until the
    // larger fits 30 bits, so the angle of a matrix axis in 24-bit fixed point keeps all its precision.
    let mut x: i64 = a;
    let mut y: i64 = b;
    let mut m: i64 = 0 as i64;
    if x < (0 as i64) {
        m = (0 as i64) - x;
    } else {
        m = x;
    }
    if y < (0 as i64) {
        if ((0 as i64) - y) > m {
            m = (0 as i64) - y;
        }
    } else if y > m {
        m = y;
    }
    while m > (1073741824 as i64) {
        x = x / (2 as i64);
        y = y / (2 as i64);
        m = m / (2 as i64);
    }
    return ev_angle(x as i32, y as i32);
}
pub(crate) fn pc_glyph(mut cx: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, code: i32, ncode: i32) -> i32 {
    // One shown glyph: look the code up, put its cell in page space, record it,
    // advance the text position by its width, the character and word spacing.
    // Recorded (SPEC 8.4.3): the box of its cell; its baseline segment from its origin to its origin plus
    // its advance without Tc and Tw (text space +x, so the spacing stays measurable); `asc` and `desc`
    // (signed distances from the baseline along the up vector, from the font's ascent and descent); `rot`
    // by `ev-angle` from the exact direction of the text matrix's x axis; its fill colour and alpha; the
    // colour-space class when the colour operators said (gray, rgb, cmyk); `z`, the page's paint counter;
    // `mark` (the innermost open mark) and `ocg` (the innermost optional-content mark).
    let slot: i32 = crate::port::cells_at(cx, C_SLOT);
    let fs: i64 = fx_get(cx, C_CUR + G_FS);
    let th: i64 = fx_get(cx, C_CUR + G_TH);
    let tc: i64 = fx_get(cx, C_CUR + G_TC);
    let tw: i64 = fx_get(cx, C_CUR + G_TW);
    let rise: i64 = fx_get(cx, C_CUR + G_RISE);
    let mut sat: i32 = 0;
    let mut cnt: i32 = 0;
    let mut cp0: i32 = -1;
    let mut how: i32 = 5;
    let mut w: i32 = -1;
    let mut asc: i32 = 0;
    let mut desc: i32 = 0;
    let mut vert: i32 = 0;
    let mut dwv: i32 = -100000;
    let mut fid: i32 = -1;
    let mut tstart: i32 = -1;
    let mut i: i32 = 0;
    let mut vch: i32 = 0;
    let mut idx: i32 = 0;
    if slot >= 0 {
        sat = C_SLOTS + (slot * SLOT_STRIDE);
        fid = crate::port::cells_at(cx, sat + S_ID);
        if fid < 0 {
            pc_warn_set(cx, W_FONTS);
        }
        if crate::port::cells_at(cx, sat + S_STATUS) == 0 {
            cnt = pc_f_map(f0, f1, f2, f3, slot, code);
            how = pc_f_how(f0, f1, f2, f3, slot);
            w = pc_f_width(f0, f1, f2, f3, slot, code);
            asc = crate::port::cells_at(cx, sat + S_ASC);
            desc = crate::port::cells_at(cx, sat + S_DESC);
            vert = crate::port::cells_at(cx, sat + S_VERT);
            dwv = crate::port::cells_at(cx, sat + S_DW2W);
        }
    }
    if cnt > 0 {
        cp0 = pc_f_cp(f0, f1, f2, f3, slot, 0);
    }
    // A composite font's ToUnicode may say U+0000 or U+FFFD for a glyph it has no value
    // for (Skia does, for the parts of a Devanagari conjunct): that is no value.
    if (cnt == 1) && ((cp0 == 0) || (cp0 == 65533)) {
        cnt = 0;
        cp0 = -1;
        how = 5;
    }
    if w < 0 {
        w = 50000;
        pc_warn_set(cx, W_WIDTH);
    }
    if (asc == 0) && (desc == 0) {
        asc = 800;
        desc = -200;
    }
    let wfx: i64 = fx_muldiv(w as i64, fs, 100000 as i64);
    let mut x0t: i64 = 0 as i64;
    let mut x1t: i64 = 0 as i64;
    let mut y0t: i64 = 0 as i64;
    let mut y1t: i64 = 0 as i64;
    if vert == 0 {
        x1t = fx_mul(wfx, th);
        y0t = (fx_muldiv(desc as i64, fs, 1000 as i64)).wrapping_add(rise);
        y1t = (fx_muldiv(asc as i64, fs, 1000 as i64)).wrapping_add(rise);
    } else {
        x0t = (0 as i64) - (wfx / (2 as i64));
        x1t = wfx / (2 as i64);
        y0t = (fx_muldiv(dwv as i64, fs, 100000 as i64)).wrapping_add(rise);
        y1t = rise;
    }
    let p0x: i64 = mx_x(cx, C_M, x0t, y0t);
    let p0y: i64 = mx_y(cx, C_M, x0t, y0t);
    let p1x: i64 = mx_x(cx, C_M, x1t, y0t);
    let p1y: i64 = mx_y(cx, C_M, x1t, y0t);
    let p2x: i64 = mx_x(cx, C_M, x0t, y1t);
    let p2y: i64 = mx_y(cx, C_M, x0t, y1t);
    let p3x: i64 = mx_x(cx, C_M, x1t, y1t);
    let p3y: i64 = mx_y(cx, C_M, x1t, y1t);
    let ma: i64 = fx_get(cx, C_M);
    let mb: i64 = fx_get(cx, C_M + 2);
    let mc: i64 = fx_get(cx, C_M + 4);
    let md: i64 = fx_get(cx, C_M + 6);
    let hyp: i64 = fx_hypot(mc, md);
    let size: i32 = fx_round(fx_mul(hyp, fx_abs(fs)));
    let rot: i32 = pc_dir_angle(ma, mb);
    let bx0: i32 = fx_round(mx_x(cx, C_M, 0 as i64, rise));
    let by0: i32 = fx_round(mx_y(cx, C_M, 0 as i64, rise));
    let bx1: i32 = fx_round(mx_x(cx, C_M, fx_mul(wfx, th), rise));
    let by1: i32 = fx_round(mx_y(cx, C_M, fx_mul(wfx, th), rise));
    let up: i32 = fx_round(fx_mul(y1t - rise, hyp));
    let down: i32 = fx_round(fx_mul(y0t - rise, hyp));
    let fam: i32 = crate::port::cells_at(cx, C_CUR + G_FAM);
    let z: i32 = crate::port::cells_at(cx, C_Z);
    let g: i32 = gl_new(gl, crate::port::cells_at(cx, C_PAGE), fx_round(pc_min4(p0x, p1x, p2x, p3x)), fx_round(pc_min4(p0y, p1y, p2y, p3y)), fx_round(pc_max4(p0x, p1x, p2x, p3x)), fx_round(pc_max4(p0y, p1y, p2y, p3y)), cp0, -1, 0, -1);
    gl_set(gl, g, gf_how(), how);
    gl_set(gl, g, gf_font(), fid);
    gl_set(gl, g, gf_size(), size);
    gl_set(gl, g, gf_bx0(), bx0);
    gl_set(gl, g, gf_by0(), by0);
    gl_set(gl, g, gf_bx1(), bx1);
    gl_set(gl, g, gf_by1(), by1);
    if up >= down {
        gl_set(gl, g, gf_asc(), up);
        gl_set(gl, g, gf_desc(), down);
    } else {
        gl_set(gl, g, gf_asc(), down);
        gl_set(gl, g, gf_desc(), up);
    }
    gl_set(gl, g, gf_rot(), rot);
    gl_set(gl, g, gf_fill(), crate::port::cells_at(cx, C_CUR + G_COLOR));
    gl_set(gl, g, gf_falpha(), crate::port::cells_at(cx, C_CUR + G_ALPHA));
    gl_set(gl, g, gf_stroke(), crate::port::cells_at(cx, C_CUR + G_SCOLOR));
    gl_set(gl, g, gf_salpha(), crate::port::cells_at(cx, C_CUR + G_SALPHA));
    gl_set(gl, g, gf_clip(), crate::port::cells_at(cx, C_CUR + G_CLIP));
    gl_set(gl, g, gf_mode(), crate::port::cells_at(cx, C_CUR + G_MODE));
    if (fam > 0) && (crate::port::cells_at(cx, C_CUR + G_MODE) != 1) && (crate::port::cells_at(cx, C_CUR + G_MODE) != 5) {
        gl_set(gl, g, gf_cs(), fam);
    }
    if (crate::port::cells_at(cx, C_CUR + G_SFAM) > 0) && ((crate::port::cells_at(cx, C_CUR + G_MODE) == 1) || (crate::port::cells_at(cx, C_CUR + G_MODE) == 5)) {
        gl_set(gl, g, gf_cs(), crate::port::cells_at(cx, C_CUR + G_SFAM));
    }
    if crate::port::cells_at(cx, C_CUR + G_BM) != 0 {
        vch = vc_blend();
    }
    if crate::port::cells_at(cx, C_CUR + G_SMASK) != 0 {
        vch += vc_softmask();
    }
    gl_set(gl, g, gf_vchk(), vch);
    if crate::port::cells_at(cx, C_CUR + G_MODE) >= 4 {
        if crate::port::cells_at(cx, C_TCN) == 0 {
            crate::port::cells_set(cx, C_TCX0, gl_get(gl, g, ch_x0()));
            crate::port::cells_set(cx, C_TCY0, gl_get(gl, g, ch_y0()));
            crate::port::cells_set(cx, C_TCX1, gl_get(gl, g, ch_x1()));
            crate::port::cells_set(cx, C_TCY1, gl_get(gl, g, ch_y1()));
        } else {
            if gl_get(gl, g, ch_x0()) < crate::port::cells_at(cx, C_TCX0) {
                crate::port::cells_set(cx, C_TCX0, gl_get(gl, g, ch_x0()));
            }
            if gl_get(gl, g, ch_y0()) < crate::port::cells_at(cx, C_TCY0) {
                crate::port::cells_set(cx, C_TCY0, gl_get(gl, g, ch_y0()));
            }
            if gl_get(gl, g, ch_x1()) > crate::port::cells_at(cx, C_TCX1) {
                crate::port::cells_set(cx, C_TCX1, gl_get(gl, g, ch_x1()));
            }
            if gl_get(gl, g, ch_y1()) > crate::port::cells_at(cx, C_TCY1) {
                crate::port::cells_set(cx, C_TCY1, gl_get(gl, g, ch_y1()));
            }
        }
        crate::port::cells_set(cx, C_TCN, crate::port::cells_at(cx, C_TCN) + 1);
    }
    gl_set(gl, g, gf_z(), z);
    crate::port::cells_set(cx, C_Z, z + 1);
    gl_set(gl, g, gf_mark(), crate::port::cells_at(cx, C_MCTOP));
    gl_set(gl, g, gf_ocg(), crate::port::cells_at(cx, C_CUROCG));
    if cnt > 1 {
        i = 0;
        while i < cnt {
            idx = etx_append_cp(et, pc_f_cp(f0, f1, f2, f3, slot, i));
            if i == 0 {
                tstart = idx;
            }
            i += 1;
        }
        gl_set(gl, g, ch_tstart(), tstart);
        gl_set(gl, g, ch_tlen(), cnt);
    }
    // The advance: tx = (w0 * Tfs + Tc + Tw) * Th, or ty = w1 * Tfs + Tc + Tw.
    let mut adv: i64 = 0 as i64;
    if vert == 0 {
        adv = (wfx).wrapping_add(tc);
    } else {
        adv = (fx_muldiv(dwv as i64, fs, 100000 as i64)).wrapping_add(tc);
    }
    if (code == 32) && (ncode == 1) {
        adv = (adv).wrapping_add(tw);
    }
    if vert == 0 {
        pc_advance(cx, fx_mul(adv, th), 0 as i64);
    } else {
        pc_advance(cx, 0 as i64, adv);
    }
    return 0;
}
pub(crate) fn pc_show_str(mut cx: &mut crate::port::Cells, ox: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, s: i32) -> i32 {
    // Show the string operand s: split it into codes by the font's codespace.
    let start: i32 = pc_ea(ox, s);
    let ln: i32 = pc_eb(ox, s);
    let slot: i32 = crate::port::cells_at(cx, C_SLOT);
    let mut okfont: i32 = 0;
    let mut i: i32 = 0;
    let mut n: i32 = 1;
    let mut code: i32 = 0;
    let mut k: i32 = 0;
    let mut b0: i32 = 0;
    let mut b1: i32 = -1;
    let mut b2: i32 = -1;
    let mut b3: i32 = -1;
    if slot >= 0 {
        if crate::port::cells_at(cx, (C_SLOTS + (slot * SLOT_STRIDE)) + S_STATUS) == 0 {
            okfont = 1;
        }
    }
    while i < ln {
        b0 = crate::port::cells_at(ox, start + i);
        b1 = -1;
        b2 = -1;
        b3 = -1;
        if (i + 1) < ln {
            b1 = crate::port::cells_at(ox, start + (i + 1));
        }
        if (i + 2) < ln {
            b2 = crate::port::cells_at(ox, start + (i + 2));
        }
        if (i + 3) < ln {
            b3 = crate::port::cells_at(ox, start + (i + 3));
        }
        n = 1;
        if okfont == 1 {
            n = pc_f_code_len(f0, f1, f2, f3, slot, b0, b1, b2, b3);
        }
        if n < 1 {
            n = 1;
        }
        if n > 4 {
            n = 4;
        }
        if (i + n) > ln {
            n = ln - i;
        }
        code = 0;
        k = 0;
        while k < n {
            if (n == 4) && ((k == 0) && (crate::port::cells_at(ox, start + i) >= 128)) {
                code = (crate::port::cells_at(ox, start + i) - 256) * 16777216;
            } else {
                code = (code * 256) + crate::port::cells_at(ox, start + (i + k));
            }
            k += 1;
        }
        pc_glyph(cx, gl, et, f0, f1, f2, f3, code, n);
        i += n;
    }
    return 0;
}
pub(crate) fn pc_show_arr(mut cx: &mut crate::port::Cells, ox: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, s: i32) -> i32 {
    // TJ: strings and adjustments. An adjustment n moves the position by
    // -n/1000 of the font size (along x, scaled by Th; along y in vertical mode).
    let cnt: i32 = pc_ea(ox, s);
    let slot: i32 = crate::port::cells_at(cx, C_SLOT);
    let fs: i64 = fx_get(cx, C_CUR + G_FS);
    let th: i64 = fx_get(cx, C_CUR + G_TH);
    let mut vert: i32 = 0;
    let mut j: i32 = s + 1;
    let mut k: i32 = 0;
    let mut delta: i64 = 0 as i64;
    if slot >= 0 {
        vert = crate::port::cells_at(cx, (C_SLOTS + (slot * SLOT_STRIDE)) + S_VERT);
    }
    while j < ((s + 1) + cnt) {
        k = pc_kind(ox, j);
        if k == K_STR {
            pc_show_str(cx, ox, gl, et, f0, f1, f2, f3, j);
        }
        if k == K_NUM {
            delta = (0 as i64) - fx_muldiv(fx_mul(fx_join(pc_ea(ox, j), pc_eb(ox, j)), fs), 1 as i64, 1000 as i64);
            if vert == 0 {
                pc_advance(cx, fx_mul(delta, th), 0 as i64);
            } else {
                pc_advance(cx, 0 as i64, delta);
            }
        }
        j += pc_esize(ox, j);
    }
    return 0;
}
pub(crate) static PC_PDFDOC_TAB: [i32; 41] = [
    728, 711, 710, 729, 733, 731, 730, 732, 8226, 8224, 8225, 8230, 8212, 8211, 402, 8260,
    8249, 8250, 8722, 8240, 8222, 8220, 8221, 8216, 8217, 8218, 8482, 64257, 64258, 321, 338, 352,
    376, 381, 305, 322, 339, 353, 382, 65533, 8364
];
pub(crate) fn pc_pdfdoc(c: i32) -> i32 {
    // PDFDocEncoding (Annex D.2) to Unicode: Latin-1 except 0x18-0x1F, 0x80-0xA0.
    if (c >= 24) && (c <= 31) {
        return PC_PDFDOC_TAB[(c - 24) as usize];
    }
    if (c >= 128) && (c <= 160) {
        return PC_PDFDOC_TAB[(8 + (c - 128)) as usize];
    }
    return c;
}
pub(crate) fn pc_push_bytes(mut et: &mut crate::port::Cells, ox: &mut crate::port::Cells, start: i32, ln: i32) -> i32 {
    // A name's bytes as code points (Latin-1), into the evidence text. Answers
    // the index of the first.
    let at: i32 = crate::port::cells_len(et);
    let mut k: i32 = 0;
    while k < ln {
        etx_append_cp(et, crate::port::cells_at(ox, start + k));
        k += 1;
    }
    return at;
}
pub(crate) fn pc_push_entry(mut et: &mut crate::port::Cells, ox: &mut crate::port::Cells, i: i32) -> i32 {
    // The bytes of name operand i into the evidence text; the index of the first.
    let s: i32 = pc_ea(ox, i);
    let ln: i32 = pc_eb(ox, i);
    return pc_push_bytes(et, ox, s, ln);
}
pub(crate) fn pc_push_utf16(mut et: &mut crate::port::Cells, ox: &mut crate::port::Cells, start: i32, ln: i32, little: i32) -> i32 {
    // UTF-16 text from ox[start, start+ln) (after the byte order mark), into
    // the evidence text: surrogate pairs joined, a lone surrogate U+FFFD, and
    // the language escapes of PDF 2.0 (U+001B ... U+001B) dropped.
    let mut k: i32 = 0;
    let mut u: i32 = 0;
    let mut u2: i32 = 0;
    let mut skip: i32 = 0;
    while (k + 1) < ln {
        if little == 1 {
            u = crate::port::cells_at(ox, start + k) + (crate::port::cells_at(ox, start + (k + 1)) * 256);
        } else {
            u = (crate::port::cells_at(ox, start + k) * 256) + crate::port::cells_at(ox, start + (k + 1));
        }
        k += 2;
        if (u >= 55296) && (u <= 56319) && ((k + 1) < ln) {
            if little == 1 {
                u2 = crate::port::cells_at(ox, start + k) + (crate::port::cells_at(ox, start + (k + 1)) * 256);
            } else {
                u2 = (crate::port::cells_at(ox, start + k) * 256) + crate::port::cells_at(ox, start + (k + 1));
            }
            if (u2 >= 56320) && (u2 <= 57343) {
                u = 65536 + (((u - 55296) * 1024) + (u2 - 56320));
                k += 2;
            }
        }
        if u == 27 {
            skip = 1 - skip;
        } else if skip == 0 {
            etx_append_cp(et, u);
        }
    }
    return 0;
}
pub(crate) fn pc_push_utf8(mut et: &mut crate::port::Cells, ox: &mut crate::port::Cells, start: i32, ln: i32) -> i32 {
    let mut k: i32 = 0;
    let mut c: i32 = 0;
    let mut need: i32 = 0;
    let mut v: i32 = 0;
    let mut j: i32 = 0;
    let mut ok: i32 = 0;
    while k < ln {
        c = crate::port::cells_at(ox, start + k);
        k += 1;
        need = 0;
        v = c;
        if c >= 240 {
            need = 3;
            v = c - 240;
        } else if c >= 224 {
            need = 2;
            v = c - 224;
        } else if c >= 192 {
            need = 1;
            v = c - 192;
        }
        ok = 1;
        if (c >= 128) && (c < 192) {
            ok = 0;
        }
        if c > 247 {
            ok = 0;
        }
        j = 0;
        while (ok == 1) && (j < need) {
            if (k < ln) && ((crate::port::cells_at(ox, start + k) >= 128) && (crate::port::cells_at(ox, start + k) < 192)) {
                v = (v * 64) + (crate::port::cells_at(ox, start + k) - 128);
                k += 1;
            } else {
                ok = 0;
            }
            j += 1;
        }
        if ok == 1 {
            etx_append_cp(et, v);
        } else {
            etx_append_cp(et, 65533);
        }
    }
    return 0;
}
pub(crate) fn pc_push_text(mut et: &mut crate::port::Cells, ox: &mut crate::port::Cells, start: i32, ln: i32) -> i32 {
    // A PDF text string (UTF-16BE or LE with a byte order mark, UTF-8 with its
    // BOM, else PDFDocEncoding) into the evidence text. Answers the first index.
    let at: i32 = crate::port::cells_len(et);
    let mut k: i32 = 0;
    if (ln >= 2) && ((crate::port::cells_at(ox, start) == 254) && (crate::port::cells_at(ox, start + 1) == 255)) {
        pc_push_utf16(et, ox, start + 2, ln - 2, 0);
        return at;
    }
    if (ln >= 2) && ((crate::port::cells_at(ox, start) == 255) && (crate::port::cells_at(ox, start + 1) == 254)) {
        pc_push_utf16(et, ox, start + 2, ln - 2, 1);
        return at;
    }
    if (ln >= 3) && ((crate::port::cells_at(ox, start) == 239) && ((crate::port::cells_at(ox, start + 1) == 187) && (crate::port::cells_at(ox, start + 2) == 191))) {
        pc_push_utf8(et, ox, start + 3, ln - 3);
        return at;
    }
    while k < ln {
        etx_append_cp(et, pc_pdfdoc(crate::port::cells_at(ox, start + k)));
        k += 1;
    }
    return at;
}
pub(crate) fn pc_ar_fx64(ar: &mut crate::port::Cells, h: i32) -> i64 {
    let kind: i32 = pl_kind_of(ar, h);
    if kind == 2 {
        return fx_of_int(pl_int_value(ar, h));
    }
    if kind == 3 {
        return fx_of_real(pl_int_value(ar, h), pl_ref_gen(ar, h));
    }
    return 0 as i64;
}
pub(crate) fn pc_ingest_props(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut ox: &mut crate::port::Cells, dict: i32) -> i32 {
    // Copy the pairs of a /Properties dictionary that marked content reads
    // into the operand entries as a dictionary entry, so one reader serves an
    // inline property list and a named one. Answers the entry's index.
    let d: i32 = pc_ox_push(cx, ox, K_DICT, 0, 0, 0);
    let mut k: i32 = pl_first(ar, dict);
    let mut v: i32 = 0;
    let mut vr: i32 = 0;
    let mut want: i32 = 0;
    let mut kind: i32 = 0;
    let mut at: i32 = 0;
    let mut j: i32 = 0;
    let mut ln: i32 = 0;
    let mut fxv: i64 = 0 as i64;
    if d < 0 {
        return -1;
    }
    while k != 0 {
        v = pl_next(ar, k);
        want = 0;
        if pl_kind_of(ar, k) == 4 {
            if (pl_name_is(ar, k, pn_mcid()) == 1) || ((pl_name_is(ar, k, pn_actual_text()) == 1) || ((pl_name_is(ar, k, pn_alt()) == 1) || ((pl_name_is(ar, k, pn_e()) == 1) || ((pl_name_is(ar, k, pn_lang()) == 1) || ((pl_name_is(ar, k, pn_type()) == 1) || (pl_name_is(ar, k, pn_subtype()) == 1)))))) {
                want = 1;
            }
        }
        if (want == 1) && (v != 0) {
            vr = pd_resolve(src, ar, dc, a, b, st, v);
            kind = 0;
            if vr != 0 {
                kind = pl_kind_of(ar, vr);
            }
            if (kind == 2) || (kind == 3) {
                fxv = pc_ar_fx64(ar, vr);
                // The key, then the number.
                ln = pl_name_len(ar, k);
                at = crate::port::cells_len(ox);
                j = 0;
                while j < ln {
                    crate::port::cells_push(ox, pl_name_byte(ar, k, j));
                    j += 1;
                }
                pc_ox_push(cx, ox, K_NAME, at, ln, 0);
                pc_ox_push(cx, ox, K_NUM, fx_hi(fxv), fx_lo(fxv), 1);
            }
            if (kind == 4) || (kind == 5) {
                ln = pl_name_len(ar, k);
                at = crate::port::cells_len(ox);
                j = 0;
                while j < ln {
                    crate::port::cells_push(ox, pl_name_byte(ar, k, j));
                    j += 1;
                }
                pc_ox_push(cx, ox, K_NAME, at, ln, 0);
                ln = pl_str_len(ar, vr);
                at = crate::port::cells_len(ox);
                j = 0;
                if kind == 4 {
                    while j < ln {
                        crate::port::cells_push(ox, pl_name_byte(ar, vr, j));
                        j += 1;
                    }
                } else {
                    while j < ln {
                        crate::port::cells_push(ox, pl_str_byte(ar, vr, j));
                        j += 1;
                    }
                }
                if kind == 4 {
                    pc_ox_push(cx, ox, K_NAME, at, ln, 0);
                } else {
                    pc_ox_push(cx, ox, K_STR, at, ln, 0);
                }
            }
        }
        if v == 0 {
            k = 0;
        } else {
            k = pl_next(ar, v);
        }
    }
    crate::port::cells_set(ox, (d * 4) + 1, (crate::port::cells_at(cx, C_OXN) - d) - 1);
    return d;
}
pub(crate) fn pc_read_props(mut et: &mut crate::port::Cells, mut mk: &mut crate::port::Cells, ox: &mut crate::port::Cells, span: i32, d: i32, isart: i32) -> i32 {
    // Fill the mark's fields from the dictionary entry d of the operands: MCID, ActualText, Alt, E, Lang;
    // and, for an /Artifact, its /Type and /Subtype as codes (`ar`: pagination, layout, background, page,
    // else `other`; `as`: header, footer, watermark, else `other`). A name that is none of the known ones
    // is not kept (SPEC 8.4.3 holds codes, D101 held the name).
    let end: i32 = (d + 1) + pc_ea(ox, d);
    let mut j: i32 = d + 1;
    let mut v: i32 = 0;
    let mut ks: i32 = 0;
    let mut kl: i32 = 0;
    let mut vs: i32 = 0;
    let mut vl: i32 = 0;
    let mut vk: i32 = 0;
    let mut at: i32 = 0;
    while j < end {
        v = j + 1;
        if (pc_kind(ox, j) == K_NAME) && (v < end) {
            ks = pc_ea(ox, j);
            kl = pc_eb(ox, j);
            vk = pc_kind(ox, v);
            vs = pc_ea(ox, v);
            vl = pc_eb(ox, v);
            if (pc_name_eq(ox, ks, kl, pn_mcid()) == 1) && (vk == K_NUM) {
                mk_set(mk, span, mkf_mcid(), fx_round(fx_join(vs, vl)));
            }
            if (isart == 1) && ((pc_name_eq(ox, ks, kl, pn_type()) == 1) && (vk == K_NAME)) {
                mk_set(mk, span, mkf_artype(), ar_other());
                if pc_name_eq(ox, vs, vl, pn_pagination()) == 1 {
                    mk_set(mk, span, mkf_artype(), ar_pagination());
                }
                if pc_name_eq(ox, vs, vl, pn_layout()) == 1 {
                    mk_set(mk, span, mkf_artype(), ar_layout());
                }
                if pc_name_eq(ox, vs, vl, pn_background()) == 1 {
                    mk_set(mk, span, mkf_artype(), ar_background());
                }
                if pc_name_eq(ox, vs, vl, pn_page()) == 1 {
                    mk_set(mk, span, mkf_artype(), ar_page());
                }
            }
            if (isart == 1) && ((pc_name_eq(ox, ks, kl, pn_subtype()) == 1) && (vk == K_NAME)) {
                mk_set(mk, span, mkf_arsub(), as_other());
                if pc_name_eq(ox, vs, vl, pn_header()) == 1 {
                    mk_set(mk, span, mkf_arsub(), as_header());
                }
                if pc_name_eq(ox, vs, vl, pn_footer()) == 1 {
                    mk_set(mk, span, mkf_arsub(), as_footer());
                }
                if pc_name_eq(ox, vs, vl, pn_watermark()) == 1 {
                    mk_set(mk, span, mkf_arsub(), as_watermark());
                }
            }
            if (vk == K_STR) || (vk == K_NAME) {
                if pc_name_eq(ox, ks, kl, pn_actual_text()) == 1 {
                    at = pc_push_text(et, ox, vs, vl);
                    mk_set(mk, span, mkf_actual(), at);
                    mk_set(mk, span, mkf_actuallen(), crate::port::cells_len(et) - at);
                }
                if pc_name_eq(ox, ks, kl, pn_alt()) == 1 {
                    at = pc_push_text(et, ox, vs, vl);
                    mk_set(mk, span, mkf_alt(), at);
                    mk_set(mk, span, mkf_altlen(), crate::port::cells_len(et) - at);
                }
                if pc_name_eq(ox, ks, kl, pn_e()) == 1 {
                    at = pc_push_text(et, ox, vs, vl);
                    mk_set(mk, span, mkf_exp(), at);
                    mk_set(mk, span, mkf_explen(), crate::port::cells_len(et) - at);
                }
                if pc_name_eq(ox, ks, kl, pn_lang()) == 1 {
                    at = pc_push_text(et, ox, vs, vl);
                    mk_set(mk, span, mkf_lang(), at);
                    mk_set(mk, span, mkf_langlen(), crate::port::cells_len(et) - at);
                }
            }
            j = v + pc_esize(ox, v);
        } else {
            j += pc_esize(ox, j);
        }
    }
    return 0;
}
pub(crate) fn pc_mc_pop(mut cx: &mut crate::port::Cells, mut mk: &mut crate::port::Cells, gl: &mut crate::port::Cells, unterminated: i32) -> i32 {
    // Close the innermost open mark: its glyphs are those shown since it opened, its painted objects
    // those numbered since (`mk-close`).
    let t: i32 = crate::port::cells_at(cx, C_MCTOP);
    if t < 0 {
        return 0;
    }
    let g: i32 = gl_count(gl);
    let par: i32 = mk_get(mk, t, mkf_parent());
    mk_close(mk, t, g, crate::port::cells_at(cx, C_Z));
    if unterminated == 1 {
        let fl: i32 = mk_get(mk, t, mkf_flags());
        mk_set(mk, t, mkf_flags(), fl | mc_unterminated());
    }
    crate::port::cells_set(cx, C_MCTOP, par);
    crate::port::cells_set(cx, C_MCDEPTH, crate::port::cells_at(cx, C_MCDEPTH) - 1);
    if crate::port::cells_at(cx, C_CUROCG) == t {
        crate::port::cells_set(cx, C_CUROCG, mk_ocg_of(mk, par));
    }
    return 0;
}
pub(crate) fn pc_mc_begin(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut ox: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut mk: &mut crate::port::Cells, mut fnt: &mut crate::port::Cells, mut gx: &mut crate::port::Cells, n: i32, props: i32) -> i32 {
    // BMC / BDC: open a mark with the tag of operand 0 and, for BDC, the properties of operand 1 (an
    // inline dictionary, or a name in /Properties). Its kind is `artifact` for /Artifact,
    // `optional-content` for /OC (its object number is the /Properties entry's, when that is a
    // reference), else `tag`.
    let depth: i32 = crate::port::cells_at(cx, C_MCDEPTH);
    let mut tstart: i32 = 0;
    let mut tlen: i32 = 0;
    let mut span: i32 = 0;
    let mut d: i32 = -1;
    let mut raw: i32 = 0;
    let mut dh: i32 = 0;
    let mut isart: i32 = 0;
    let mut isoc: i32 = 0;
    let mut t0: i32 = 0;
    let mut kind: i32 = 3;
    let mut flags: i32 = 0;
    if depth >= MAX_MC {
        crate::port::cells_set(cx, C_MCOVER, crate::port::cells_at(cx, C_MCOVER) + 1);
        pc_warn_set(cx, W_MC);
        return 0;
    }
    tstart = crate::port::cells_len(et);
    if (n >= 1) && (pc_kind(ox, 0) == K_NAME) {
        tstart = pc_push_entry(et, ox, 0);
        tlen = pc_eb(ox, 0);
        if pc_entry_name_is(ox, 0, pn_artifact()) == 1 {
            isart = 1;
        }
        t0 = pc_ea(ox, 0);
        if (tlen == 2) && ((crate::port::cells_at(ox, t0) == 79) && (crate::port::cells_at(ox, t0 + 1) == 67)) {
            isoc = 1;
        }
    }
    if isart == 1 {
        kind = mk_artifact();
    }
    if isoc == 1 {
        kind = mk_optional_content();
    }
    span = mk_open(mk, crate::port::cells_at(cx, C_PAGE), kind, tstart, tlen, crate::port::cells_at(cx, C_MCTOP), gl_count(gl), crate::port::cells_at(cx, C_Z));
    mk_set(mk, span, mkf_stm(), crate::port::cells_at(cx, C_STM));
    if isart == 1 {
        mk_set(mk, span, mkf_artype(), ar_other());
    }
    if (props == 1) && (n >= 2) {
        if pc_kind(ox, 1) == K_DICT {
            d = 1;
            flags = mc_inline();
        }
        if pc_kind(ox, 1) == K_NAME {
            raw = pc_res_entry(src, ar, dc, a, b, st, cx, ox, pn_properties(), 1);
            if raw != 0 {
                dh = pd_resolve(src, ar, dc, a, b, st, raw);
            }
            if ps_missed(src) {
                crate::port::cells_set(cx, C_ABORT, 1);
            }
            if (isoc == 1) && (raw != 0) {
                if pl_kind_of(ar, raw) == 9 {
                    mk_set(mk, span, mkf_ocg(), pl_int_value(ar, raw));
                }
                mk_set(mk, span, mkf_ocgdef(), gx_oc_state(src, ar, dc, a, b, st, gx, raw, 0));
            }
            if (dh != 0) && (pl_kind_of(ar, dh) == 7) {
                d = pc_ingest_props(src, ar, dc, a, b, st, cx, ox, dh);
                flags = mc_resource();
            } else {
                flags = mc_unresolved();
                pc_warn_set(cx, W_PROPS);
            }
        }
        mk_set(mk, span, mkf_flags(), flags);
        if d >= 0 {
            pc_read_props(et, mk, ox, span, d, isart);
        }
    }
    crate::port::cells_set(cx, C_MCTOP, span);
    crate::port::cells_set(cx, C_MCDEPTH, depth + 1);
    if isoc == 1 {
        crate::port::cells_set(cx, C_CUROCG, span);
    }
    return 0;
}
pub(crate) fn pc_mc_end(mut cx: &mut crate::port::Cells, mut mk: &mut crate::port::Cells, gl: &mut crate::port::Cells) -> i32 {
    // EMC: close the innermost mark this stream opened; a BDC that was too deep
    // to record is balanced first; an EMC with nothing to close is ignored.
    let over: i32 = crate::port::cells_at(cx, C_MCOVER);
    if over > 0 {
        crate::port::cells_set(cx, C_MCOVER, over - 1);
        return 0;
    }
    if crate::port::cells_at(cx, C_MCDEPTH) <= crate::port::cells_at(cx, C_MCBASE) {
        pc_warn_set(cx, W_MC);
        return 0;
    }
    return pc_mc_pop(cx, mk, gl, 0);
}
pub(crate) fn pc_skip_inline(mut cx: &mut crate::port::Cells, cs: &mut crate::port::Cells) -> i32 {
    // BI: skip to the end of the inline image: find `ID` and its one white
    // space, then the first `EI` that stands alone (white space before and white
    // space or the end after). Binary data rarely contains one; if it does the
    // rest is read as operators and skipped as unknown ones.
    let end: i32 = crate::port::cells_at(cx, C_END);
    let mut p: i32 = crate::port::cells_at(cx, C_POS);
    let mut found: i32 = 0;
    while ((p + 2) < end) && (found == 0) {
        if (pc_ws(crate::port::cells_at(cs, p)) == 1) && ((crate::port::cells_at(cs, p + 1) == 73) && ((crate::port::cells_at(cs, p + 2) == 68) && (((p + 3) >= end) || (pc_ws(crate::port::cells_at(cs, p + 3)) == 1)))) {
            found = 1;
            p += 4;
        } else {
            p += 1;
        }
    }
    if found == 0 {
        crate::port::cells_set(cx, C_POS, end);
        return 0;
    }
    found = 0;
    while ((p + 1) < end) && (found == 0) {
        if (crate::port::cells_at(cs, p) == 69) && ((crate::port::cells_at(cs, p + 1) == 73) && (((p == 0) || (pc_ws(crate::port::cells_at(cs, p - 1)) == 1)) && (((p + 2) >= end) || (pc_ws(crate::port::cells_at(cs, p + 2)) == 1)))) {
            found = 1;
            p += 2;
        } else {
            p += 1;
        }
    }
    if found == 0 {
        p = end;
    }
    crate::port::cells_set(cx, C_POS, p);
    return 0;
}
pub(crate) fn pc_tx(cx: &mut crate::port::Cells, x: i64, y: i64) -> i64 {
    // The user-space point (x, y) in page space: x of it (Fx).
    return fx_clamp(mx_x(cx, C_CUR + G_CTM, x, y));
}
pub(crate) fn pc_ty(cx: &mut crate::port::Cells, x: i64, y: i64) -> i64 {
    return fx_clamp(mx_y(cx, C_CUR + G_CTM, x, y));
}
pub(crate) fn pc_flag_or(v: i32, bit: i32) -> i32 {
    // v with the one-bit flag `bit` set.
    if (v & bit) != 0 {
        return v;
    }
    return v + bit;
}
pub(crate) fn pc_path_reset(mut cx: &mut crate::port::Cells, mut pts: &mut crate::port::Cells) -> i32 {
    // No path: the next point starts one. The pts arena keeps what an earlier row of the evidence put there.
    let n: i32 = pt_count(pts);
    crate::port::cells_set(cx, C_PPTS, n);
    crate::port::cells_set(cx, C_PN, 0);
    crate::port::cells_set(cx, C_PKEEP, 0);
    crate::port::cells_set(cx, C_PBX0, 2147483647);
    crate::port::cells_set(cx, C_PBY0, 2147483647);
    crate::port::cells_set(cx, C_PBX1, -2147483647);
    crate::port::cells_set(cx, C_PBY1, -2147483647);
    crate::port::cells_set(cx, C_PFLAGS, 0);
    crate::port::cells_set(cx, C_PNSUB, 0);
    return 0;
}
pub(crate) fn pc_path_add(mut cx: &mut crate::port::Cells, mut pts: &mut crate::port::Cells, px: i64, py: i64, op: i32) -> i32 {
    // Append the page-space point (px, py) to the path: its box, the current point, and (for the first
    // PATH_KEEP points) a row of `pts`.
    let x: i32 = fx_round(px);
    let y: i32 = fx_round(py);
    let keep: i32 = crate::port::cells_at(cx, C_PKEEP);
    if x < crate::port::cells_at(cx, C_PBX0) {
        crate::port::cells_set(cx, C_PBX0, x);
    }
    if y < crate::port::cells_at(cx, C_PBY0) {
        crate::port::cells_set(cx, C_PBY0, y);
    }
    if x > crate::port::cells_at(cx, C_PBX1) {
        crate::port::cells_set(cx, C_PBX1, x);
    }
    if y > crate::port::cells_at(cx, C_PBY1) {
        crate::port::cells_set(cx, C_PBY1, y);
    }
    if (keep < PATH_KEEP_STRAIGHT) && ((pt_count(pts) - crate::port::cells_at(cx, C_PTS0)) < PTS_PAGE) {
        pt_add(pts, x, y, op);
        crate::port::cells_set(cx, C_PKEEP, keep + 1);
    } else {
        if keep < PATH_KEEP_STRAIGHT {
            pc_warn_set(cx, W_PATHS);
        }
        crate::port::cells_set(cx, C_PFLAGS, pc_flag_or(crate::port::cells_at(cx, C_PFLAGS), 4));
    }
    crate::port::cells_set(cx, C_PN, crate::port::cells_at(cx, C_PN) + 1);
    fx_put(cx, C_PCX, px);
    fx_put(cx, C_PCY, py);
    return 0;
}
pub(crate) fn pc_op_move(mut cx: &mut crate::port::Cells, mut pts: &mut crate::port::Cells, ox: &mut crate::port::Cells, n: i32) -> i32 {
    if n < 2 {
        return 0;
    }
    let x: i64 = pc_num(ox, n, 0);
    let y: i64 = pc_num(ox, n, 1);
    let px: i64 = pc_tx(cx, x, y);
    let py: i64 = pc_ty(cx, x, y);
    crate::port::cells_set(cx, C_PNSUB, crate::port::cells_at(cx, C_PNSUB) + 1);
    pc_path_add(cx, pts, px, py, po_move());
    fx_put(cx, C_PSX, px);
    fx_put(cx, C_PSY, py);
    return 0;
}
pub(crate) fn pc_op_line(mut cx: &mut crate::port::Cells, mut pts: &mut crate::port::Cells, ox: &mut crate::port::Cells, n: i32) -> i32 {
    if n < 2 {
        return 0;
    }
    if crate::port::cells_at(cx, C_PN) == 0 {
        return 0;
    }
    let x: i64 = pc_num(ox, n, 0);
    let y: i64 = pc_num(ox, n, 1);
    let px: i64 = pc_tx(cx, x, y);
    let py: i64 = pc_ty(cx, x, y);
    pc_path_add(cx, pts, px, py, po_line());
    return 0;
}
pub(crate) fn pc_op_curve(mut cx: &mut crate::port::Cells, mut pts: &mut crate::port::Cells, ox: &mut crate::port::Cells, n: i32, kind: i32) -> i32 {
    // c (kind 0, six numbers), v (kind 1: the first control point is the current point) and y (kind 2: the
    // second control point is the end point). Each puts three curve points in the path.
    if crate::port::cells_at(cx, C_PN) == 0 {
        return 0;
    }
    let mut x1: i64 = 0 as i64;
    let mut y1: i64 = 0 as i64;
    let mut x2: i64 = 0 as i64;
    let mut y2: i64 = 0 as i64;
    let mut x3: i64 = 0 as i64;
    let mut y3: i64 = 0 as i64;
    let mut q1x: i64 = 0 as i64;
    let mut q1y: i64 = 0 as i64;
    if kind == 0 {
        if n < 6 {
            return 0;
        }
        x1 = pc_num(ox, n, 0);
        y1 = pc_num(ox, n, 1);
        x2 = pc_num(ox, n, 2);
        y2 = pc_num(ox, n, 3);
        x3 = pc_num(ox, n, 4);
        y3 = pc_num(ox, n, 5);
    }
    if kind == 1 {
        if n < 4 {
            return 0;
        }
        x2 = pc_num(ox, n, 0);
        y2 = pc_num(ox, n, 1);
        x3 = pc_num(ox, n, 2);
        y3 = pc_num(ox, n, 3);
    }
    if kind == 2 {
        if n < 4 {
            return 0;
        }
        x1 = pc_num(ox, n, 0);
        y1 = pc_num(ox, n, 1);
        x3 = pc_num(ox, n, 2);
        y3 = pc_num(ox, n, 3);
        x2 = x3;
        y2 = y3;
    }
    if kind == 1 {
        q1x = fx_get(cx, C_PCX);
        q1y = fx_get(cx, C_PCY);
    } else {
        q1x = pc_tx(cx, x1, y1);
        q1y = pc_ty(cx, x1, y1);
    }
    pc_path_add(cx, pts, q1x, q1y, po_curve());
    let q2x: i64 = pc_tx(cx, x2, y2);
    let q2y: i64 = pc_ty(cx, x2, y2);
    let q3x: i64 = pc_tx(cx, x3, y3);
    let q3y: i64 = pc_ty(cx, x3, y3);
    pc_path_add(cx, pts, q2x, q2y, po_curve());
    pc_path_add(cx, pts, q3x, q3y, po_curve());
    crate::port::cells_set(cx, C_PFLAGS, pc_flag_or(crate::port::cells_at(cx, C_PFLAGS), 1));
    return 0;
}
pub(crate) fn pc_op_close(mut cx: &mut crate::port::Cells, mut pts: &mut crate::port::Cells) -> i32 {
    // h: a close row at the subpath's start, which is the current point again.
    if crate::port::cells_at(cx, C_PN) == 0 {
        return 0;
    }
    let sx: i64 = fx_get(cx, C_PSX);
    let sy: i64 = fx_get(cx, C_PSY);
    pc_path_add(cx, pts, sx, sy, po_close());
    return 0;
}
pub(crate) fn pc_rect_path(mut cx: &mut crate::port::Cells, mut pts: &mut crate::port::Cells, x: i64, y: i64, w: i64, h: i64) -> i32 {
    // The rectangle x y w h (user space) as a closed subpath of four corners, each through the CTM.
    let xw: i64 = fx_clamp((x).wrapping_add(w));
    let yh: i64 = fx_clamp((y).wrapping_add(h));
    let ax: i64 = pc_tx(cx, x, y);
    let ay: i64 = pc_ty(cx, x, y);
    let bx: i64 = pc_tx(cx, xw, y);
    let by: i64 = pc_ty(cx, xw, y);
    let dx: i64 = pc_tx(cx, xw, yh);
    let dy: i64 = pc_ty(cx, xw, yh);
    let ex: i64 = pc_tx(cx, x, yh);
    let ey: i64 = pc_ty(cx, x, yh);
    crate::port::cells_set(cx, C_PNSUB, crate::port::cells_at(cx, C_PNSUB) + 1);
    pc_path_add(cx, pts, ax, ay, po_move());
    fx_put(cx, C_PSX, ax);
    fx_put(cx, C_PSY, ay);
    pc_path_add(cx, pts, bx, by, po_line());
    pc_path_add(cx, pts, dx, dy, po_line());
    pc_path_add(cx, pts, ex, ey, po_line());
    pc_path_add(cx, pts, ax, ay, po_close());
    return 0;
}
pub(crate) fn pc_op_rect(mut cx: &mut crate::port::Cells, mut pts: &mut crate::port::Cells, ox: &mut crate::port::Cells, n: i32) -> i32 {
    // re: the rectangle x y w h.
    if n < 4 {
        return 0;
    }
    let x: i64 = pc_num(ox, n, 0);
    let y: i64 = pc_num(ox, n, 1);
    let w: i64 = pc_num(ox, n, 2);
    let h: i64 = pc_num(ox, n, 3);
    pc_rect_path(cx, pts, x, y, w, h);
    return 0;
}
pub(crate) fn pc_near(p: i32, q: i32) -> i32 {
    // 1 when two centipoint coordinates differ by at most one (a corner rounded two ways).
    let d: i32 = p - q;
    if (d <= 1) && (d >= -1) {
        return 1;
    }
    return 0;
}
pub(crate) fn pc_is_rect(mut cx: &mut crate::port::Cells, mut pts: &mut crate::port::Cells) -> i32 {
    // 1 when the path is one subpath of four corners (a line back to the first corner, and a close, allowed)
    // whose sides are axis-aligned to a centipoint.
    let n: i32 = crate::port::cells_at(cx, C_PN);
    let s: i32 = crate::port::cells_at(cx, C_PPTS);
    let mut k: i32 = 0;
    let mut np: i32 = 0;
    let mut opk: i32 = 0;
    let mut x0: i32 = 0;
    let mut y0: i32 = 0;
    let mut x1: i32 = 0;
    let mut y1: i32 = 0;
    let mut x2: i32 = 0;
    let mut y2: i32 = 0;
    let mut x3: i32 = 0;
    let mut y3: i32 = 0;
    let mut px: i32 = 0;
    let mut py: i32 = 0;
    if (n < 4) || (n > 6) {
        return 0;
    }
    if crate::port::cells_at(cx, C_PNSUB) != 1 {
        return 0;
    }
    if (crate::port::cells_at(cx, C_PFLAGS) & 5) != 0 {
        return 0;
    }
    // The points that are not a close row, in order; the first must be a move.
    while k < n {
        opk = pt_get(pts, s + k, ptf_op());
        px = pt_get(pts, s + k, ptf_x());
        py = pt_get(pts, s + k, ptf_y());
        if k == 0 {
            if opk != po_move() {
                return 0;
            }
        }
        if (k > 0) && (opk == po_move()) {
            return 0;
        }
        if opk != po_close() {
            if np == 0 {
                x0 = px;
                y0 = py;
            }
            if np == 1 {
                x1 = px;
                y1 = py;
            }
            if np == 2 {
                x2 = px;
                y2 = py;
            }
            if np == 3 {
                x3 = px;
                y3 = py;
            }
            if np == 4 {
                if (pc_near(px, x0) == 0) || (pc_near(py, y0) == 0) {
                    return 0;
                }
            }
            np += 1;
        }
        k += 1;
    }
    if (np != 4) && (np != 5) {
        return 0;
    }
    if (pc_near(x0, x1) == 1) && ((pc_near(y1, y2) == 1) && ((pc_near(x2, x3) == 1) && (pc_near(y3, y0) == 1))) {
        return 1;
    }
    if (pc_near(y0, y1) == 1) && ((pc_near(x1, x2) == 1) && ((pc_near(y2, y3) == 1) && (pc_near(x3, x0) == 1))) {
        return 1;
    }
    return 0;
}
pub(crate) fn pc_scale_cpt(cx: &mut crate::port::Cells, w: i64) -> i32 {
    // A length in user units (an Fx) as centipoints under the current CTM: through the length of its x axis.
    let a: i64 = fx_get(cx, C_CUR + G_CTM);
    let b: i64 = fx_get(cx, (C_CUR + G_CTM) + 2);
    let hyp: i64 = fx_hypot(a, b);
    let v: i32 = fx_round(fx_mul(fx_abs(w), hyp));
    if v > 10000000 {
        return 10000000;
    }
    return v;
}
pub(crate) fn pc_dash_op(mut cx: &mut crate::port::Cells, ox: &mut crate::port::Cells, n: i32) -> i32 {
    // d: the dash array's first length (centipoints under the CTM), 0 for a solid line.
    crate::port::cells_set(cx, C_CUR + G_DASH, 0);
    if n < 1 {
        return 0;
    }
    if pc_kind(ox, 0) != K_ARR {
        return 0;
    }
    if pc_ea(ox, 0) < 1 {
        return 0;
    }
    if pc_kind(ox, 1) != K_NUM {
        return 0;
    }
    let v: i64 = pc_num(ox, n, 1);
    let sc: i32 = pc_scale_cpt(cx, v);
    crate::port::cells_set(cx, C_CUR + G_DASH, sc);
    return 0;
}
pub(crate) fn pc_clip_box(mut cx: &mut crate::port::Cells, mut pa: &mut crate::port::Cells, x0: i32, y0: i32, x1: i32, y1: i32, kind: i32, flags: i32, pfirst: i32, pcount: i32) -> i32 {
    // Clip to the box (x0, y0, x1, y1) of a shape of `kind`: the region becomes its intersection with the clip in
    // force. When that does not shrink the region there is nothing to record; else a `paths` row (a clip, SPEC
    // 8.4.3: z -1) holds the intersection, naming the clip it was cut from, and becomes the clip in force.
    let cur: i32 = crate::port::cells_at(cx, C_CUR + G_CLIP);
    let mut ix0: i32 = x0;
    let mut iy0: i32 = y0;
    let mut ix1: i32 = x1;
    let mut iy1: i32 = y1;
    let mut same: i32 = 0;
    let mut cb: i32 = 0;
    let mut r: i32 = 0;
    if cur >= 0 {
        cb = pa_get(pa, cur, pf_x0());
        if cb > ix0 {
            ix0 = cb;
        }
        cb = pa_get(pa, cur, pf_y0());
        if cb > iy0 {
            iy0 = cb;
        }
        cb = pa_get(pa, cur, pf_x1());
        if cb < ix1 {
            ix1 = cb;
        }
        cb = pa_get(pa, cur, pf_y1());
        if cb < iy1 {
            iy1 = cb;
        }
        if (ix0 == pa_get(pa, cur, pf_x0())) && ((iy0 == pa_get(pa, cur, pf_y0())) && ((ix1 == pa_get(pa, cur, pf_x1())) && (iy1 == pa_get(pa, cur, pf_y1())))) {
            same = 1;
        }
    }
    if same == 1 {
        return 0;
    }
    if crate::port::cells_at(cx, C_NPATH) >= PATH_ROWS {
        pc_warn_set(cx, W_PATHS);
        return 0;
    }
    r = pa_new(pa, crate::port::cells_at(cx, C_PAGE), kind, ix0, iy0, ix1, iy1);
    pa_set(pa, r, pf_flags(), pg_clip() + flags);
    pa_set(pa, r, pf_clip(), cur);
    pa_set(pa, r, pf_mark(), crate::port::cells_at(cx, C_MCTOP));
    pa_set(pa, r, pf_ocg(), crate::port::cells_at(cx, C_CUROCG));
    pa_set(pa, r, pf_pfirst(), pfirst);
    pa_set(pa, r, pf_pcount(), pcount);
    crate::port::cells_set(cx, C_NPATH, crate::port::cells_at(cx, C_NPATH) + 1);
    crate::port::cells_set(cx, C_CUR + G_CLIP, r);
    return 0;
}
pub(crate) fn pc_kind_of_path(mut cx: &mut crate::port::Cells, mut pts: &mut crate::port::Cells) -> i32 {
    // The `pa` kind of the path: a rectangle, a curve, a single line, else other.
    if pc_is_rect(cx, pts) == 1 {
        return pa_rect();
    }
    if (crate::port::cells_at(cx, C_PFLAGS) & 1) != 0 {
        return pa_curve();
    }
    if (crate::port::cells_at(cx, C_PN) == 2) && (crate::port::cells_at(cx, C_PNSUB) == 1) {
        return pa_line();
    }
    return pa_other();
}
pub(crate) fn pc_geom_kept(cx: &mut crate::port::Cells) -> i32 {
    // 1 when the whole path is in `pts`: a path of `m l h re` alone had no more than PATH_KEEP_STRAIGHT points (and the
    // page's `pts` was not full), a path with a curve no more than PATH_KEEP (D219).
    if (crate::port::cells_at(cx, C_PFLAGS) & 4) != 0 {
        return 0;
    }
    if ((crate::port::cells_at(cx, C_PFLAGS) & 1) != 0) && (crate::port::cells_at(cx, C_PN) > PATH_KEEP) {
        return 0;
    }
    return 1;
}
pub(crate) fn pc_end_path(mut cx: &mut crate::port::Cells, mut pa: &mut crate::port::Cells, mut pts: &mut crate::port::Cells, fill: i32, stroke: i32, evenodd: i32, closed: i32) -> i32 {
    // A paint operator (or `n`) ends the path. If it filled or stroked, a `paths` row records it; then a pending
    // `W` or `W*` clips to it. The row's box is the path's box, grown by half the stroke width when it strokes;
    // its geometry is the path's rows of `pts` (kept when the path was short enough, else dropped).
    let n: i32 = crate::port::cells_at(cx, C_PN);
    let start: i32 = crate::port::cells_at(cx, C_PPTS);
    let kept: i32 = pc_geom_kept(cx);
    let pend: i32 = crate::port::cells_at(cx, C_CLIPP);
    let mut kind: i32 = 0;
    let mut half: i32 = 0;
    let mut r: i32 = 0;
    let mut fl: i32 = 0;
    let mut wd: i32 = 0;
    let mut lwv: i64 = 0 as i64;
    let mut nrows: i32 = 0;
    let mut pfst: i32 = -1;
    let mut geom: i32 = 0;
    let mut painted: i32 = 0;
    let mut tr: i32 = 0;
    crate::port::cells_set(cx, C_CLIPP, 0);
    if n == 0 {
        pc_path_reset(cx, pts);
        return 0;
    }
    kind = pc_kind_of_path(cx, pts);
    nrows = n;
    if kept == 0 {
        nrows = 0;
    }
    if kept == 0 {
        tr = pg_truncated();
    }
    if nrows > 0 {
        pfst = start;
    }
    if (kept == 0) && (crate::port::cells_at(cx, C_PKEEP) > 0) {
        crate::port::cells_drop(pts, start * 3);
    }
    geom = nrows;
    if (fill == 1) || (stroke == 1) {
        if crate::port::cells_at(cx, C_NPATH) >= PATH_ROWS {
            pc_warn_set(cx, W_PATHS);
        } else {
            painted = 1;
            fl = tr;
            if closed != 0 {
                fl += pg_closed();
            }
            if evenodd == 1 {
                fl += pg_evenodd();
            }
            if stroke == 1 {
                lwv = fx_get(cx, C_CUR + G_LW);
                wd = pc_scale_cpt(cx, lwv);
                half = (wd + 1) / 2;
                fl += pg_stroked();
            }
            if fill == 1 {
                fl += pg_filled();
                if crate::port::cells_at(cx, C_CUR + G_FAM) == 5 {
                    fl += pg_pattern();
                }
            }
            if crate::port::cells_at(cx, C_CUR + G_BM) != 0 {
                fl += pg_blend();
            }
            if crate::port::cells_at(cx, C_CUR + G_SMASK) != 0 {
                fl += pg_softmask();
            }
            r = pa_new(pa, crate::port::cells_at(cx, C_PAGE), kind, crate::port::cells_at(cx, C_PBX0) - half, crate::port::cells_at(cx, C_PBY0) - half, crate::port::cells_at(cx, C_PBX1) + half, crate::port::cells_at(cx, C_PBY1) + half);
            pa_set(pa, r, pf_flags(), fl);
            if fill == 1 {
                pa_set(pa, r, pf_fill(), crate::port::cells_at(cx, C_CUR + G_COLOR));
            }
            if stroke == 1 {
                pa_set(pa, r, pf_stroke(), crate::port::cells_at(cx, C_CUR + G_SCOLOR));
                pa_set(pa, r, pf_width(), wd);
                pa_set(pa, r, pf_dash(), crate::port::cells_at(cx, C_CUR + G_DASH));
            }
            pa_set(pa, r, pf_falpha(), crate::port::cells_at(cx, C_CUR + G_ALPHA));
            pa_set(pa, r, pf_salpha(), crate::port::cells_at(cx, C_CUR + G_SALPHA));
            pa_set(pa, r, pf_z(), crate::port::cells_at(cx, C_Z));
            crate::port::cells_set(cx, C_Z, crate::port::cells_at(cx, C_Z) + 1);
            pa_set(pa, r, pf_clip(), crate::port::cells_at(cx, C_CUR + G_CLIP));
            pa_set(pa, r, pf_mark(), crate::port::cells_at(cx, C_MCTOP));
            pa_set(pa, r, pf_ocg(), crate::port::cells_at(cx, C_CUROCG));
            pa_set(pa, r, pf_pfirst(), pfst);
            pa_set(pa, r, pf_pcount(), geom);
            crate::port::cells_set(cx, C_NPATH, crate::port::cells_at(cx, C_NPATH) + 1);
        }
    }
    if pend != 0 {
        fl = tr;
        if pend == 2 {
            fl += pg_evenodd();
        }
        pc_clip_box(cx, pa, crate::port::cells_at(cx, C_PBX0), crate::port::cells_at(cx, C_PBY0), crate::port::cells_at(cx, C_PBX1), crate::port::cells_at(cx, C_PBY1), kind, fl, pfst, geom);
    }
    // A path whose geometry nobody kept leaves no rows behind.
    if (painted == 0) && (pend == 0) {
        crate::port::cells_drop(pts, start * 3);
    }
    pc_path_reset(cx, pts);
    return 0;
}
pub(crate) fn pc_paint_op(mut cx: &mut crate::port::Cells, mut pa: &mut crate::port::Cells, mut pts: &mut crate::port::Cells, op: i32) -> i32 {
    // S s f F f* B B* b b* n: which of fill, stroke, even-odd and close each one means.
    let mut fill: i32 = 0;
    let mut stroke: i32 = 0;
    let mut eo: i32 = 0;
    let mut shut: i32 = 0;
    if op == OP_STROKE {
        stroke = 1;
    }
    if op == OP_CLOSESTROKE {
        stroke = 1;
        shut = 1;
    }
    if (op == OP_FILL) || (op == OP_FILL2) {
        fill = 1;
    }
    if op == OP_FILLEO {
        fill = 1;
        eo = 1;
    }
    if op == OP_FS {
        fill = 1;
        stroke = 1;
    }
    if op == OP_FSEO {
        fill = 1;
        stroke = 1;
        eo = 1;
    }
    if op == OP_CFS {
        fill = 1;
        stroke = 1;
        shut = 1;
    }
    if op == OP_CFSEO {
        fill = 1;
        stroke = 1;
        shut = 1;
        eo = 1;
    }
    if shut == 1 {
        pc_op_close(cx, pts);
    }
    pc_end_path(cx, pa, pts, fill, stroke, eo, shut);
    return 0;
}
pub(crate) fn pc_set_ink(mut cx: &mut crate::port::Cells, stroke: i32, key: i32, cls: i32, rgb: i32) -> i32 {
    // Make (key, class, colour) the fill (stroke 0) or stroking (stroke 1) colour of the current state.
    if stroke == 1 {
        crate::port::cells_set(cx, C_CUR + G_SCS, key);
        crate::port::cells_set(cx, C_CUR + G_SFAM, cls);
        crate::port::cells_set(cx, C_CUR + G_SCOLOR, rgb);
    } else {
        crate::port::cells_set(cx, C_CUR + G_FCS, key);
        crate::port::cells_set(cx, C_CUR + G_FAM, cls);
        crate::port::cells_set(cx, C_CUR + G_COLOR, rgb);
    }
    return 0;
}
pub(crate) fn pc_device_rgb(ox: &mut crate::port::Cells, mut gx: &mut crate::port::Cells, n: i32, space: i32) -> i32 {
    // The colour of the first operands under DeviceGray (space 1), DeviceRGB (2) or DeviceCMYK (3): -1 when there are
    // too few. The conversion is the colour module's, so a colour is the same however it was set.
    let mut need: i32 = 1;
    let mut i: i32 = 0;
    let mut v: i64 = 0 as i64;
    if space == 2 {
        need = 3;
    }
    if space == 3 {
        need = 4;
    }
    if n < need {
        return -1;
    }
    while i < need {
        v = pc_num(ox, n, i);
        gx_input(gx, i, v);
        i += 1;
    }
    return gx_entry_rgb(gx, space - 1, need);
}
pub(crate) fn pc_color_device(mut cx: &mut crate::port::Cells, ox: &mut crate::port::Cells, mut gx: &mut crate::port::Cells, n: i32, stroke: i32, space: i32) -> i32 {
    // g rg k G RG K: the device space, its class, and the colour.
    let rgb: i32 = pc_device_rgb(ox, gx, n, space);
    if rgb < 0 {
        return 0;
    }
    pc_set_ink(cx, stroke, 0 - space, space, rgb);
    return 0;
}
pub(crate) fn pc_cs_op(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, ox: &mut crate::port::Cells, mut gx: &mut crate::port::Cells, n: i32, stroke: i32) -> i32 {
    // cs, CS: the colour space named by operand 0: a device space, Pattern, or a /ColorSpace resource. The colour
    // becomes the space's initial colour. A space this reader cannot read leaves an unknown colour (-1) and no class.
    if n < 1 {
        return 0;
    }
    if pc_kind(ox, 0) != K_NAME {
        return 0;
    }
    let mut key: i32 = 0;
    let mut raw: i32 = 0;
    let mut h: i32 = 0;
    let mut e: i32 = -1;
    if pc_entry_name_is(ox, 0, pn_device_gray()) == 1 {
        key = -1;
    }
    if pc_entry_name_is(ox, 0, pn_device_rgb()) == 1 {
        key = -2;
    }
    if pc_entry_name_is(ox, 0, pn_device_cmyk()) == 1 {
        key = -3;
    }
    if pc_entry_name_is(ox, 0, pn_pattern()) == 1 {
        key = -4;
    }
    if key == 0 {
        raw = pc_res_entry(src, ar, dc, a, b, st, cx, ox, pn_color_space(), 0);
        if raw != 0 {
            h = pd_resolve(src, ar, dc, a, b, st, raw);
        }
        if ps_missed(src) {
            crate::port::cells_set(cx, C_ABORT, 1);
            return 0;
        }
        if h != 0 {
            key = gx_key_of(src, ar, dc, a, b, st, h);
        }
    }
    if key != 0 {
        e = gx_lookup(src, ar, dc, a, b, st, out, gx, key);
    }
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
        return 0;
    }
    if e < 0 {
        pc_set_ink(cx, stroke, key, 0, -1);
        return 0;
    }
    let cls: i32 = gx_class(gx, e);
    let rgb: i32 = gx_initial(gx, e);
    pc_set_ink(cx, stroke, key, cls, rgb);
    return 0;
}
pub(crate) fn pc_sc_op(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, ox: &mut crate::port::Cells, mut gx: &mut crate::port::Cells, n: i32, stroke: i32) -> i32 {
    // sc, scn, SC, SCN: a colour in the current space. A pattern space takes no components (its colour is
    // unknown); a colour whose component count is not the space's is read by its count, as a device colour.
    let mut key: i32 = 0;
    let mut e: i32 = -1;
    let mut nn: i32 = 0;
    let mut i: i32 = 0;
    let mut ncomp: i32 = 0;
    let mut rgb: i32 = -1;
    let mut cls: i32 = 0;
    let mut v: i64 = 0 as i64;
    if stroke == 1 {
        key = crate::port::cells_at(cx, C_CUR + G_SCS);
    } else {
        key = crate::port::cells_at(cx, C_CUR + G_FCS);
    }
    if key != 0 {
        e = gx_lookup(src, ar, dc, a, b, st, out, gx, key);
    }
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
        return 0;
    }
    while (nn < n) && (pc_kind(ox, nn) == K_NUM) {
        nn += 1;
    }
    if e == -1 {
        // A space that is not known: whatever colour was set is not.
        pc_set_ink(cx, stroke, key, 0, -1);
        return 0;
    }
    if gx_is_pattern(gx, e) == 1 {
        pc_set_ink(cx, stroke, key, 5, -1);
        return 0;
    }
    ncomp = gx_ncomp(gx, e);
    if nn > 32 {
        nn = 32;
    }
    if (nn > 0) && (nn == ncomp) {
        i = 0;
        while i < nn {
            v = pc_num(ox, n, i);
            gx_input(gx, i, v);
            i += 1;
        }
        rgb = gx_entry_rgb(gx, e, nn);
        cls = gx_class(gx, e);
        pc_set_ink(cx, stroke, key, cls, rgb);
        return 0;
    }
    // The operands do not fit the space: read them by count, as a device colour, and keep the space.
    if (nn > 0) && ((nn == 1) || ((nn == 3) || (nn == 4))) {
        if nn == 1 {
            rgb = pc_device_rgb(ox, gx, n, 1);
        }
        if nn == 3 {
            rgb = pc_device_rgb(ox, gx, n, 2);
        }
        if nn == 4 {
            rgb = pc_device_rgb(ox, gx, n, 3);
        }
        if stroke == 1 {
            crate::port::cells_set(cx, C_CUR + G_SCOLOR, rgb);
        } else {
            crate::port::cells_set(cx, C_CUR + G_COLOR, rgb);
        }
    }
    return 0;
}
pub(crate) fn pc_bm_code(ar: &mut crate::port::Cells, h: i32) -> i32 {
    // A blend mode name's code: 0 Normal and Compatible, 1 Multiply, 2 Screen, 3 Overlay, 4 Darken, 5 Lighten,
    // 6 ColorDodge, 7 ColorBurn, 8 HardLight, 9 SoftLight, 10 Difference, 11 Exclusion, 12 Hue, 13 Saturation,
    // 14 Color, 15 Luminosity, 99 a name that is none of those.
    if h == 0 {
        return 0;
    }
    if pl_kind_of(ar, h) != 4 {
        return 0;
    }
    if (px_is(ar, h, px_normal()) == 1) || (px_is(ar, h, px_compatible()) == 1) {
        return 0;
    }
    if px_is(ar, h, px_multiply()) == 1 {
        return 1;
    }
    if px_is(ar, h, px_screen()) == 1 {
        return 2;
    }
    if px_is(ar, h, px_overlay()) == 1 {
        return 3;
    }
    if px_is(ar, h, px_darken()) == 1 {
        return 4;
    }
    if px_is(ar, h, px_lighten()) == 1 {
        return 5;
    }
    if px_is(ar, h, px_color_dodge()) == 1 {
        return 6;
    }
    if px_is(ar, h, px_color_burn()) == 1 {
        return 7;
    }
    if px_is(ar, h, px_hard_light()) == 1 {
        return 8;
    }
    if px_is(ar, h, px_soft_light()) == 1 {
        return 9;
    }
    if px_is(ar, h, px_difference()) == 1 {
        return 10;
    }
    if px_is(ar, h, px_exclusion()) == 1 {
        return 11;
    }
    if px_is(ar, h, px_hue()) == 1 {
        return 12;
    }
    if px_is(ar, h, px_saturation()) == 1 {
        return 13;
    }
    if px_is(ar, h, px_color()) == 1 {
        return 14;
    }
    if px_is(ar, h, px_luminosity()) == 1 {
        return 15;
    }
    return 99;
}
pub(crate) fn pc_alpha_of(ar: &mut crate::port::Cells, h: i32) -> i32 {
    // A constant alpha as per-mille, clamped to 0..1000.
    let al: i32 = fx_round(fx_mul(pc_ar_fx64(ar, h), fx_of_int(1000)));
    if al < 0 {
        return 0;
    }
    if al > 1000 {
        return 1000;
    }
    return al;
}
pub(crate) fn pc_gs_op(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, ox: &mut crate::port::Cells, n: i32) -> i32 {
    // gs: the entries of the named ExtGState that matter here: /ca and /CA (alpha), /BM (the blend mode, the first
    // name of an array), /SMask (/None, or a dictionary: its /S, Alpha or Luminosity) and /LW (the line width).
    if n < 1 {
        return 0;
    }
    if pc_kind(ox, 0) != K_NAME {
        return 0;
    }
    let raw: i32 = pc_res_entry(src, ar, dc, a, b, st, cx, ox, pn_ext_g_state(), 0);
    let mut gd: i32 = 0;
    let mut v: i32 = 0;
    let mut s: i32 = 0;
    if raw == 0 {
        return 0;
    }
    gd = pd_resolve(src, ar, dc, a, b, st, raw);
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
        return 0;
    }
    if gd == 0 {
        return 0;
    }
    v = pd_dget(src, ar, dc, a, b, st, gd, pn_ca());
    if v != 0 {
        crate::port::cells_set(cx, C_CUR + G_ALPHA, pc_alpha_of(ar, v));
    }
    v = px_dget(src, ar, dc, a, b, st, gd, px_ca());
    if v != 0 {
        crate::port::cells_set(cx, C_CUR + G_SALPHA, pc_alpha_of(ar, v));
    }
    v = px_dget(src, ar, dc, a, b, st, gd, px_bm());
    if v != 0 {
        if pl_kind_of(ar, v) == 6 {
            s = pl_first(ar, v);
            v = pd_resolve(src, ar, dc, a, b, st, s);
        }
        crate::port::cells_set(cx, C_CUR + G_BM, pc_bm_code(ar, v));
    }
    v = px_dget(src, ar, dc, a, b, st, gd, px_s_mask());
    if v != 0 {
        if pl_kind_of(ar, v) == 4 {
            crate::port::cells_set(cx, C_CUR + G_SMASK, 0);
        }
        if pl_kind_of(ar, v) == 7 {
            s = px_dget(src, ar, dc, a, b, st, v, px_s());
            crate::port::cells_set(cx, C_CUR + G_SMASK, 2);
            if px_is(ar, s, px_alpha()) == 1 {
                crate::port::cells_set(cx, C_CUR + G_SMASK, 1);
            }
        }
    }
    v = px_dget(src, ar, dc, a, b, st, gd, px_lw());
    if v != 0 {
        if px_is_num(ar, v) == 1 {
            fx_put(cx, C_CUR + G_LW, pc_ar_fx64(ar, v));
        }
    }
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
    }
    return 0;
}
pub(crate) fn pc_image_place(mut cx: &mut crate::port::Cells, mut im: &mut crate::port::Cells, obj: i32, pxw: i32, pxh: i32, flags: i32) -> i32 {
    // One image placement (SPEC 8.4.3): the unit square through the CTM. Its box is that parallelogram's, its `rot` the
    // angle of the image's x axis, `skewed` 1 when its axes are not at a right angle (to half a degree).
    let one: i64 = fx_one();
    let zero: i64 = 0 as i64;
    let ma: i64 = fx_get(cx, C_CUR + G_CTM);
    let mb: i64 = fx_get(cx, (C_CUR + G_CTM) + 2);
    let mc: i64 = fx_get(cx, (C_CUR + G_CTM) + 4);
    let md: i64 = fx_get(cx, (C_CUR + G_CTM) + 6);
    let ax: i64 = pc_tx(cx, zero, zero);
    let ay: i64 = pc_ty(cx, zero, zero);
    let bx: i64 = pc_tx(cx, one, zero);
    let by: i64 = pc_ty(cx, one, zero);
    let dx: i64 = pc_tx(cx, one, one);
    let dy: i64 = pc_ty(cx, one, one);
    let ex: i64 = pc_tx(cx, zero, one);
    let ey: i64 = pc_ty(cx, zero, one);
    let rot: i32 = pc_dir_angle(ma, mb);
    let roty: i32 = pc_dir_angle(mc, md);
    let mut diff: i32 = 0;
    let mut skew: i32 = 1;
    let mut fl: i32 = flags;
    let mut chk: i32 = 0;
    let mut ori: i32 = 0;
    let mut r: i32 = 0;
    if crate::port::cells_at(cx, C_CUR + G_BM) != 0 {
        fl += mg_blend();
    }
    if crate::port::cells_at(cx, C_CUR + G_SMASK) != 0 {
        fl += mg_softmask();
    }
    if crate::port::cells_at(cx, C_CUR + G_BM) != 0 {
        chk += vc_blend();
    }
    if crate::port::cells_at(cx, C_CUR + G_SMASK) != 0 {
        chk += vc_softmask();
    }
    diff = roty - rot;
    if diff < 0 {
        diff += 36000;
    }
    if (diff >= 8950) && (diff <= 9050) {
        skew = 0;
    }
    if (diff >= 26950) && (diff <= 27050) {
        skew = 0;
    }
    if crate::port::cells_at(cx, C_NIMG) >= PATH_ROWS {
        pc_warn_set(cx, W_PATHS);
        return 0;
    }
    r = im_new(im, crate::port::cells_at(cx, C_PAGE), fx_round(pc_min4(ax, bx, dx, ex)), fx_round(pc_min4(ay, by, dy, ey)), fx_round(pc_max4(ax, bx, dx, ex)), fx_round(pc_max4(ay, by, dy, ey)), obj, pxw, pxh);
    im_set(im, r, mf_alpha(), crate::port::cells_at(cx, C_CUR + G_ALPHA));
    im_set(im, r, mf_flags(), fl);
    im_set(im, r, mf_rot(), rot);
    im_set(im, r, mf_skewed(), skew);
    // The CTM here maps to the displayed page, whose y runs down: `pi-orient` reads a y-up matrix, so the y axis is flipped
    // back (b and d change sign). 0 is upright on the page AS DISPLAYED (a page's /Rotate is in it), 8 not rectilinear.
    ori = pi_orient(ma, (mb).wrapping_mul(-1 as i64), mc, (md).wrapping_mul(-1 as i64));
    if ori < 0 {
        ori = 8;
    }
    im_set(im, r, mf_placement(), ori);
    im_set(im, r, mf_z(), crate::port::cells_at(cx, C_Z));
    crate::port::cells_set(cx, C_Z, crate::port::cells_at(cx, C_Z) + 1);
    im_set(im, r, mf_clip(), crate::port::cells_at(cx, C_CUR + G_CLIP));
    im_set(im, r, mf_mark(), crate::port::cells_at(cx, C_MCTOP));
    im_set(im, r, mf_ocg(), crate::port::cells_at(cx, C_CUROCG));
    im_set(im, r, mf_vchk(), chk);
    crate::port::cells_set(cx, C_NIMG, crate::port::cells_at(cx, C_NIMG) + 1);
    return 0;
}
pub(crate) fn pc_oc_open(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut gx: &mut crate::port::Cells, gl: &mut crate::port::Cells, et: &mut crate::port::Cells, mut mk: &mut crate::port::Cells, raw: i32) -> i32 {
    // Open an optional-content span for the /OC entry `raw` of a Form XObject or an image (a `marks` row, kind
    // optional-content, flagged `xobject`): its state is `gx-oc-state`'s. Answers 1 when opened, 0 when spans are
    // too deep. The caller closes it with `pc-mc-pop`.
    let depth: i32 = crate::port::cells_at(cx, C_MCDEPTH);
    let mut span: i32 = 0;
    let mut state: i32 = 1;
    if depth >= MAX_MC {
        return 0;
    }
    state = gx_oc_state(src, ar, dc, a, b, st, gx, raw, 0);
    span = mk_open(mk, crate::port::cells_at(cx, C_PAGE), mk_optional_content(), crate::port::cells_len(et), 0, crate::port::cells_at(cx, C_MCTOP), gl_count(gl), crate::port::cells_at(cx, C_Z));
    mk_set(mk, span, mkf_stm(), crate::port::cells_at(cx, C_STM));
    mk_set(mk, span, mkf_flags(), mc_xobject());
    mk_set(mk, span, mkf_ocgdef(), state);
    if pl_kind_of(ar, raw) == 9 {
        mk_set(mk, span, mkf_ocg(), pl_int_value(ar, raw));
    }
    crate::port::cells_set(cx, C_MCTOP, span);
    crate::port::cells_set(cx, C_MCDEPTH, depth + 1);
    crate::port::cells_set(cx, C_CUROCG, span);
    return 1;
}
pub(crate) fn pc_image_do(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut gx: &mut crate::port::Cells, gl: &mut crate::port::Cells, et: &mut crate::port::Cells, mut mk: &mut crate::port::Cells, mut im: &mut crate::port::Cells, objnum: i32, xh: i32) -> i32 {
    // Do of an image XObject: a placement row. Its width and height are the dictionary's; the mask flags say what
    // could make it translucent (a stencil mask, an /SMask, a /Mask); an /OC makes it a span of its own.
    let w: i32 = pd_dint(src, ar, dc, a, b, st, xh, pn_width(), 0);
    let h: i32 = pd_dint(src, ar, dc, a, b, st, xh, pn_height(), 0);
    let mut fl: i32 = 0;
    let mut v: i32 = 0;
    let mut ocraw: i32 = 0;
    let mut opened: i32 = 0;
    v = px_dget(src, ar, dc, a, b, st, xh, px_image_mask());
    if v != 0 {
        if (pl_kind_of(ar, v) == 1) && (pl_int_value(ar, v) == 1) {
            fl += mg_mask();
        }
    }
    v = px_dget(src, ar, dc, a, b, st, xh, px_s_mask());
    if v != 0 {
        fl += mg_smask();
    }
    v = px_dget(src, ar, dc, a, b, st, xh, px_mask());
    if v != 0 {
        fl += mg_masked();
    }
    ocraw = px_get(ar, xh, px_oc());
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
        return 0;
    }
    if ocraw != 0 {
        opened = pc_oc_open(src, ar, dc, a, b, st, cx, gx, gl, et, mk, ocraw);
    }
    pc_image_place(cx, im, objnum, w, h, fl);
    if opened == 1 {
        pc_mc_pop(cx, mk, gl, 0);
    }
    return 0;
}
pub(crate) fn pc_name_px(ox: &mut crate::port::Cells, s: i32, l: i32, id: i32) -> i32 {
    // 1 when the name operand bytes ox[s, s+l) are row `id` of the catalogue name table (emon.pdfxnames).
    let n: i32 = PX_SPAN[(id * 2 + 1) as usize];
    let o: i32 = PX_SPAN[(id * 2 + 0) as usize];
    let mut i: i32 = 0;
    if l != n {
        return 0;
    }
    while i < n {
        if crate::port::cells_at(ox, s + i) != PX_CHARS[(o + i) as usize] {
            return 0;
        }
        i += 1;
    }
    return 1;
}
pub(crate) fn pc_find_id(cx: &mut crate::port::Cells, cs: &mut crate::port::Cells) -> i32 {
    // BI: where the `ID` that ends the inline image's dictionary starts (the index of its `I`), or -1.
    let end: i32 = crate::port::cells_at(cx, C_END);
    let mut p: i32 = crate::port::cells_at(cx, C_POS);
    while (p + 2) < end {
        if (pc_ws(crate::port::cells_at(cs, p)) == 1) && ((crate::port::cells_at(cs, p + 1) == 73) && ((crate::port::cells_at(cs, p + 2) == 68) && (((p + 3) >= end) || (pc_ws(crate::port::cells_at(cs, p + 3)) == 1)))) {
            return p + 1;
        }
        p += 1;
    }
    return -1;
}
pub(crate) fn pc_inline_image(mut cx: &mut crate::port::Cells, mut ox: &mut crate::port::Cells, cs: &mut crate::port::Cells, mut im: &mut crate::port::Cells) -> i32 {
    // BI: read the dictionary up to `ID` (width, height, whether it is a stencil mask), record the placement, then
    // leave the lexer where it was for `pc-skip-inline` to find the end of the data.
    let start: i32 = crate::port::cells_at(cx, C_POS);
    let end: i32 = crate::port::cells_at(cx, C_END);
    let idp: i32 = pc_find_id(cx, cs);
    let mut w: i32 = 0;
    let mut h: i32 = 0;
    let mut fl: i32 = 0;
    let mut j: i32 = 0;
    let mut v: i32 = 0;
    let mut ks: i32 = 0;
    let mut kl: i32 = 0;
    let mut r: i32 = 1;
    let mut total: i32 = 0;
    let mut nxt: i32 = 0;
    if idp < 0 {
        pc_image_place(cx, im, 0, 0, 0, mg_inline());
        return 0;
    }
    crate::port::cells_set(cx, C_END, idp);
    pc_ox_clear(cx, ox);
    while r == 1 {
        r = pc_lex(cx, ox, cs);
        if r == 2 {
            r = 0;
        }
    }
    total = crate::port::cells_at(cx, C_OXN);
    j = 0;
    while j < total {
        nxt = j + 1;
        if (pc_kind(ox, j) == K_NAME) && (nxt < total) {
            ks = pc_ea(ox, j);
            kl = pc_eb(ox, j);
            if pc_kind(ox, nxt) == K_NUM {
                v = fx_round(fx_join(pc_ea(ox, nxt), pc_eb(ox, nxt)));
                if (pc_name_eq(ox, ks, kl, pn_width()) == 1) || (pc_name_eq(ox, ks, kl, pn_w()) == 1) {
                    w = v;
                }
                if (pc_name_eq(ox, ks, kl, pn_height()) == 1) || (pc_name_px(ox, ks, kl, px_h()) == 1) {
                    h = v;
                }
            }
            if pc_kind(ox, nxt) == K_BOOL {
                if (pc_name_px(ox, ks, kl, px_im()) == 1) || (pc_name_px(ox, ks, kl, px_image_mask()) == 1) {
                    if pc_ea(ox, nxt) == 1 {
                        fl = mg_mask();
                    }
                }
            }
            j = nxt + pc_esize(ox, nxt);
        } else {
            j += pc_esize(ox, j);
        }
    }
    crate::port::cells_set(cx, C_END, end);
    crate::port::cells_set(cx, C_POS, start);
    pc_ox_clear(cx, ox);
    pc_image_place(cx, im, 0, w, h, mg_inline() + fl);
    return 0;
}
pub(crate) fn pc_sh_op(mut cx: &mut crate::port::Cells, mut pa: &mut crate::port::Cells) -> i32 {
    // sh: a shading fills the whole clip region. A row of kind `other`, flagged `shading`, whose box is the region's
    // (the page when nothing clips) and whose colour is unknown: P3.6 reads it as paint that is not exactly known.
    let cur: i32 = crate::port::cells_at(cx, C_CUR + G_CLIP);
    let mut r: i32 = 0;
    let mut bx0: i32 = 0;
    let mut by0: i32 = 0;
    let mut bx1: i32 = 0;
    let mut by1: i32 = 0;
    let mut fl: i32 = 0;
    if crate::port::cells_at(cx, C_NPATH) >= PATH_ROWS {
        pc_warn_set(cx, W_PATHS);
        return 0;
    }
    bx0 = 0;
    by0 = 0;
    bx1 = crate::port::cells_at(cx, C_PW);
    by1 = crate::port::cells_at(cx, C_PH);
    if cur >= 0 {
        bx0 = pa_get(pa, cur, pf_x0());
        by0 = pa_get(pa, cur, pf_y0());
        bx1 = pa_get(pa, cur, pf_x1());
        by1 = pa_get(pa, cur, pf_y1());
    }
    r = pa_new(pa, crate::port::cells_at(cx, C_PAGE), pa_other(), bx0, by0, bx1, by1);
    fl = pg_filled() + pg_shading();
    if crate::port::cells_at(cx, C_CUR + G_BM) != 0 {
        fl += pg_blend();
    }
    if crate::port::cells_at(cx, C_CUR + G_SMASK) != 0 {
        fl += pg_softmask();
    }
    pa_set(pa, r, pf_flags(), fl);
    pa_set(pa, r, pf_falpha(), crate::port::cells_at(cx, C_CUR + G_ALPHA));
    pa_set(pa, r, pf_z(), crate::port::cells_at(cx, C_Z));
    crate::port::cells_set(cx, C_Z, crate::port::cells_at(cx, C_Z) + 1);
    pa_set(pa, r, pf_clip(), cur);
    pa_set(pa, r, pf_mark(), crate::port::cells_at(cx, C_MCTOP));
    pa_set(pa, r, pf_ocg(), crate::port::cells_at(cx, C_CUROCG));
    crate::port::cells_set(cx, C_NPATH, crate::port::cells_at(cx, C_NPATH) + 1);
    return 0;
}
pub(crate) fn pc_append_stream(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut cs: &mut crate::port::Cells, sh: i32) -> i32 {
    // Decode stream sh and append its bytes (and a line feed) to `cs`. Answers
    // the filter chain's status (0 ok), or -1 when the source missed.
    let status: i32 = pd_stream_data(src, ar, dc, a, b, st, sh, out);
    let n: i32 = crate::port::cells_len(out);
    let mut i: i32 = 0;
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
        return -1;
    }
    if status != 0 {
        pc_warn_set(cx, W_STREAM);
        crate::port::cells_set(cx, C_SSTAT, status);
    }
    while i < n {
        crate::port::cells_push(cs, crate::port::cells_at(out, i));
        i += 1;
    }
    crate::port::cells_push(cs, 10);
    return status;
}
pub(crate) fn pc_do(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut ox: &mut crate::port::Cells, mut cs: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut mk: &mut crate::port::Cells, mut fnt: &mut crate::port::Cells, mut pa: &mut crate::port::Cells, mut im: &mut crate::port::Cells, mut pts: &mut crate::port::Cells, mut gx: &mut crate::port::Cells, n: i32) -> i32 {
    // Do: an image XObject is a placement (`pc-image-do`); a Form XObject is run. The form's /Matrix is
    // concatenated to the CTM, its /BBox clips (a rectangle in its own space), its /Resources replace the current
    // ones (else they are inherited), an /OC makes it an optional-content span, and it runs inside its own `q`/`Q`.
    if n < 1 {
        return 0;
    }
    if pc_kind(ox, 0) != K_NAME {
        return 0;
    }
    let raw: i32 = pc_res_entry(src, ar, dc, a, b, st, cx, ox, pn_x_object(), 0);
    let mut objnum: i32 = 0;
    let mut xh: i32 = 0;
    let mut sub: i32 = 0;
    let mut fd: i32 = 0;
    let mut i: i32 = 0;
    let mut mat: i32 = 0;
    let mut el: i32 = 0;
    let mut got: i32 = 0;
    let mut res: i32 = 0;
    let mut oldres: i32 = 0;
    let mut oldstm: i32 = 0;
    let mut start: i32 = 0;
    let mut endcs: i32 = 0;
    let mut status: i32 = 0;
    let mut bb: i32 = 0;
    let mut ocraw: i32 = 0;
    let mut opened: i32 = 0;
    let mut bx0: i64 = 0 as i64;
    let mut by0: i64 = 0 as i64;
    let mut bx1: i64 = 0 as i64;
    let mut by1: i64 = 0 as i64;
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
        return 0;
    }
    if raw == 0 {
        pc_warn_set(cx, W_FORM);
        return 0;
    }
    if pl_kind_of(ar, raw) == 9 {
        objnum = pl_int_value(ar, raw);
    }
    xh = pd_resolve(src, ar, dc, a, b, st, raw);
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
        return 0;
    }
    if xh == 0 {
        pc_warn_set(cx, W_FORM);
        return 0;
    }
    if pl_kind_of(ar, xh) != 8 {
        return 0;
    }
    sub = pd_dget(src, ar, dc, a, b, st, xh, pn_subtype());
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
        return 0;
    }
    if sub == 0 {
        return 0;
    }
    if pl_name_is(ar, sub, pn_image()) == 1 {
        pc_image_do(src, ar, dc, a, b, st, cx, gx, gl, et, mk, im, objnum, xh);
        return 0;
    }
    if pl_name_is(ar, sub, pn_form()) == 0 {
        return 0;
    }
    // Depth and cycles: a form deeper than FORM_DEPTH, or already running, is skipped.
    fd = crate::port::cells_at(cx, C_FDEPTH);
    if (fd >= MAX_FORMS) || (fd >= crate::port::cells_at(cx, C_FLIM)) {
        pc_warn_set(cx, W_DEPTH);
        return 0;
    }
    if objnum != 0 {
        while i < fd {
            if crate::port::cells_at(cx, C_FSTACK + i) == objnum {
                pc_warn_set(cx, W_DEPTH);
                return 0;
            }
            i += 1;
        }
    }
    // Its /Matrix (six numbers, else the identity).
    mx_ident(cx, C_TMP);
    mat = pd_dget(src, ar, dc, a, b, st, xh, pn_matrix());
    if (mat != 0) && (pl_kind_of(ar, mat) == 6) {
        el = pl_first(ar, mat);
        got = 0;
        while (el != 0) && (got < 6) {
            fx_put(cx, C_TMP + (got * 2), pc_ar_fx64(ar, el));
            el = pl_next(ar, el);
            got += 1;
        }
        if got < 6 {
            mx_ident(cx, C_TMP);
        }
    }
    // Its /BBox, kept as four Fx until the form's state is made.
    bb = pd_dget(src, ar, dc, a, b, st, xh, pn_b_box());
    got = 0;
    if (bb != 0) && (pl_kind_of(ar, bb) == 6) {
        el = pl_first(ar, bb);
        while (el != 0) && (got < 4) {
            sub = pd_resolve(src, ar, dc, a, b, st, el);
            if px_is_num(ar, sub) == 0 {
                got = 0;
                el = 0;
            } else {
                fx_put(cx, C_BB + (got * 2), pc_ar_fx64(ar, sub));
                el = pl_next(ar, el);
                got += 1;
            }
        }
    }
    ocraw = px_get(ar, xh, px_oc());
    res = pd_dget(src, ar, dc, a, b, st, xh, pn_resources());
    oldres = crate::port::cells_at(cx, C_RES);
    oldstm = crate::port::cells_at(cx, C_STM);
    if (res != 0) && (pl_kind_of(ar, res) == 7) {
        crate::port::cells_set(cx, C_RES, res);
    }
    start = crate::port::cells_len(cs);
    status = pc_append_stream(src, ar, dc, a, b, st, cx, out, cs, xh);
    if status == -1 {
        return 0;
    }
    pc_save(cx);
    mx_mul(cx, C_CUR + G_CTM, C_TMP, C_CUR + G_CTM);
    if got == 4 {
        // The form's box clips what it paints: a rectangle through the CTM.
        pc_path_reset(cx, pts);
        bx0 = fx_get(cx, C_BB);
        by0 = fx_get(cx, C_BB + 2);
        bx1 = fx_get(cx, C_BB + 4);
        by1 = fx_get(cx, C_BB + 6);
        pc_rect_path(cx, pts, bx0, by0, bx1 - bx0, by1 - by0);
        crate::port::cells_set(cx, C_CLIPP, 1);
        pc_end_path(cx, pa, pts, 0, 0, 0, 1);
    }
    if ocraw != 0 {
        opened = pc_oc_open(src, ar, dc, a, b, st, cx, gx, gl, et, mk, ocraw);
    }
    crate::port::cells_set(cx, C_FSTACK + fd, objnum);
    crate::port::cells_set(cx, C_FDEPTH, fd + 1);
    crate::port::cells_set(cx, C_STM, objnum);
    endcs = crate::port::cells_len(cs);
    pc_run(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pa, im, pts, gx, start, endcs);
    if opened == 1 {
        pc_mc_pop(cx, mk, gl, 0);
    }
    crate::port::cells_set(cx, C_FDEPTH, fd);
    crate::port::cells_set(cx, C_STM, oldstm);
    crate::port::cells_set(cx, C_RES, oldres);
    pc_restore(cx);
    crate::port::cells_drop(cs, start);
    return 0;
}
pub(crate) fn pc_prep(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, mut fnt: &mut crate::port::Cells, mut et: &mut crate::port::Cells) -> i32 {
    // Before a string is shown: the font resident, and M = Tm x CTM current.
    pc_ensure_font(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3, fnt, et);
    pc_update_m(cx);
    if crate::port::cells_at(cx, C_SLOT) < 0 {
        pc_warn_set(cx, W_TEXT);
    }
    return 0;
}
pub(crate) fn pc_op(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut ox: &mut crate::port::Cells, mut cs: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut mk: &mut crate::port::Cells, mut fnt: &mut crate::port::Cells, mut pa: &mut crate::port::Cells, mut im: &mut crate::port::Cells, mut pts: &mut crate::port::Cells, mut gx: &mut crate::port::Cells, op: i32, n: i32) -> i32 {
    // Execute one operator; `ox` holds its n operands. Unknown operators do
    // nothing (their operands are dropped by the caller).
    if op == OP_SAVE {
        pc_save(cx);
        return 0;
    }
    if op == OP_RESTORE {
        pc_restore(cx);
        return 0;
    }
    if op == OP_CM {
        if n >= 6 {
            mx_set(cx, C_TMP, pc_num(ox, n, 0), pc_num(ox, n, 1), pc_num(ox, n, 2), pc_num(ox, n, 3), pc_num(ox, n, 4), pc_num(ox, n, 5));
            mx_mul(cx, C_CUR + G_CTM, C_TMP, C_CUR + G_CTM);
        }
        return 0;
    }
    if op == OP_BT {
        mx_ident(cx, C_TM);
        mx_ident(cx, C_TLM);
        crate::port::cells_set(cx, C_INTEXT, 1);
        crate::port::cells_set(cx, C_TCN, 0);
        return 0;
    }
    if op == OP_ET {
        crate::port::cells_set(cx, C_INTEXT, 0);
        if crate::port::cells_at(cx, C_TCN) > 0 {
            // Glyphs shown in a clipping render mode (4 to 7) clip to their boxes' union (a superset of the glyphs).
            pc_clip_box(cx, pa, crate::port::cells_at(cx, C_TCX0), crate::port::cells_at(cx, C_TCY0), crate::port::cells_at(cx, C_TCX1), crate::port::cells_at(cx, C_TCY1), pa_other(), 0, -1, 0);
            crate::port::cells_set(cx, C_TCN, 0);
        }
        return 0;
    }
    if op == OP_TF {
        pc_tf(src, ar, dc, a, b, st, cx, ox, n);
        return 0;
    }
    if op == OP_TCHAR {
        fx_put(cx, C_CUR + G_TC, pc_num(ox, n, 0));
        return 0;
    }
    if op == OP_TWORD {
        fx_put(cx, C_CUR + G_TW, pc_num(ox, n, 0));
        return 0;
    }
    if op == OP_TSCALE {
        fx_put(cx, C_CUR + G_TH, fx_muldiv(pc_num(ox, n, 0), 1 as i64, 100 as i64));
        return 0;
    }
    if op == OP_TLEAD {
        fx_put(cx, C_CUR + G_TL, pc_num(ox, n, 0));
        return 0;
    }
    if op == OP_TRISE {
        fx_put(cx, C_CUR + G_RISE, pc_num(ox, n, 0));
        return 0;
    }
    if op == OP_TMODE {
        crate::port::cells_set(cx, C_CUR + G_MODE, fx_round(pc_num(ox, n, 0)));
        return 0;
    }
    if op == OP_TD {
        pc_td(cx, pc_num(ox, n, 0), pc_num(ox, n, 1));
        return 0;
    }
    if op == OP_TDL {
        fx_put(cx, C_CUR + G_TL, (0 as i64) - pc_num(ox, n, 1));
        pc_td(cx, pc_num(ox, n, 0), pc_num(ox, n, 1));
        return 0;
    }
    if op == OP_TM {
        if n >= 6 {
            pc_set_tm(cx, pc_num(ox, n, 0), pc_num(ox, n, 1), pc_num(ox, n, 2), pc_num(ox, n, 3), pc_num(ox, n, 4), pc_num(ox, n, 5));
        }
        return 0;
    }
    if op == OP_TSTAR {
        pc_next_line(cx);
        return 0;
    }
    if op == OP_SHOW {
        if (n >= 1) && (pc_kind(ox, 0) == K_STR) {
            pc_prep(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3, fnt, et);
            pc_show_str(cx, ox, gl, et, f0, f1, f2, f3, 0);
        }
        return 0;
    }
    if op == OP_SHOWARR {
        if (n >= 1) && (pc_kind(ox, 0) == K_ARR) {
            pc_prep(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3, fnt, et);
            pc_show_arr(cx, ox, gl, et, f0, f1, f2, f3, 0);
        }
        return 0;
    }
    if op == OP_QUOTE {
        if (n >= 1) && (pc_kind(ox, 0) == K_STR) {
            pc_next_line(cx);
            pc_prep(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3, fnt, et);
            pc_show_str(cx, ox, gl, et, f0, f1, f2, f3, 0);
        }
        return 0;
    }
    if op == OP_DQUOTE {
        if (n >= 3) && (pc_kind(ox, 2) == K_STR) {
            fx_put(cx, C_CUR + G_TW, pc_num(ox, n, 0));
            fx_put(cx, C_CUR + G_TC, pc_num(ox, n, 1));
            pc_next_line(cx);
            pc_prep(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3, fnt, et);
            pc_show_str(cx, ox, gl, et, f0, f1, f2, f3, 2);
        }
        return 0;
    }
    if op == OP_DO {
        pc_do(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pa, im, pts, gx, n);
        return 0;
    }
    if op == OP_BDC {
        pc_mc_begin(src, ar, dc, a, b, st, cx, ox, gl, et, mk, fnt, gx, n, 1);
        return 0;
    }
    if op == OP_BMC {
        pc_mc_begin(src, ar, dc, a, b, st, cx, ox, gl, et, mk, fnt, gx, n, 0);
        return 0;
    }
    if op == OP_EMC {
        pc_mc_end(cx, mk, gl);
        return 0;
    }
    if op == OP_BI {
        pc_inline_image(cx, ox, cs, im);
        pc_skip_inline(cx, cs);
        return 0;
    }
    // Colour: the device operators, the named spaces, the components.
    if op == OP_GRAY {
        pc_color_device(cx, ox, gx, n, 0, 1);
        return 0;
    }
    if op == OP_RGB {
        pc_color_device(cx, ox, gx, n, 0, 2);
        return 0;
    }
    if op == OP_CMYK {
        pc_color_device(cx, ox, gx, n, 0, 3);
        return 0;
    }
    if op == OP_GRAY_S {
        pc_color_device(cx, ox, gx, n, 1, 1);
        return 0;
    }
    if op == OP_RGB_S {
        pc_color_device(cx, ox, gx, n, 1, 2);
        return 0;
    }
    if op == OP_CMYK_S {
        pc_color_device(cx, ox, gx, n, 1, 3);
        return 0;
    }
    if (op == OP_SC) || (op == OP_SCN) {
        pc_sc_op(src, ar, dc, a, b, st, out, cx, ox, gx, n, 0);
        return 0;
    }
    if (op == OP_SC_S) || (op == OP_SCN_S) {
        pc_sc_op(src, ar, dc, a, b, st, out, cx, ox, gx, n, 1);
        return 0;
    }
    if op == OP_CS {
        pc_cs_op(src, ar, dc, a, b, st, out, cx, ox, gx, n, 0);
        return 0;
    }
    if op == OP_CS_S {
        pc_cs_op(src, ar, dc, a, b, st, out, cx, ox, gx, n, 1);
        return 0;
    }
    if op == OP_GS {
        pc_gs_op(src, ar, dc, a, b, st, cx, ox, n);
        return 0;
    }
    // Paths: construction, painting, clipping.
    if op == OP_MOVE {
        pc_op_move(cx, pts, ox, n);
        return 0;
    }
    if op == OP_LINE {
        pc_op_line(cx, pts, ox, n);
        return 0;
    }
    if op == OP_CURVE {
        pc_op_curve(cx, pts, ox, n, 0);
        return 0;
    }
    if op == OP_CURVE_V {
        pc_op_curve(cx, pts, ox, n, 1);
        return 0;
    }
    if op == OP_CURVE_Y {
        pc_op_curve(cx, pts, ox, n, 2);
        return 0;
    }
    if op == OP_CLOSE {
        pc_op_close(cx, pts);
        return 0;
    }
    if op == OP_RECT {
        pc_op_rect(cx, pts, ox, n);
        return 0;
    }
    if (op == OP_STROKE) || ((op == OP_CLOSESTROKE) || ((op == OP_FILL) || ((op == OP_FILL2) || ((op == OP_FILLEO) || ((op == OP_FS) || ((op == OP_FSEO) || ((op == OP_CFS) || (op == OP_CFSEO)))))))) {
        pc_paint_op(cx, pa, pts, op);
        return 0;
    }
    if op == OP_ENDPATH {
        pc_end_path(cx, pa, pts, 0, 0, 0, 0);
        return 0;
    }
    if op == OP_CLIP {
        crate::port::cells_set(cx, C_CLIPP, 1);
        return 0;
    }
    if op == OP_CLIPEO {
        crate::port::cells_set(cx, C_CLIPP, 2);
        return 0;
    }
    if op == OP_SH {
        pc_sh_op(cx, pa);
        return 0;
    }
    if op == OP_LW {
        fx_put(cx, C_CUR + G_LW, pc_num(ox, n, 0));
        return 0;
    }
    if op == OP_DASH {
        pc_dash_op(cx, ox, n);
        return 0;
    }
    return 0;
}
pub(crate) fn pc_run(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut ox: &mut crate::port::Cells, mut cs: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut mk: &mut crate::port::Cells, mut fnt: &mut crate::port::Cells, mut pa: &mut crate::port::Cells, mut im: &mut crate::port::Cells, mut pts: &mut crate::port::Cells, mut gx: &mut crate::port::Cells, start: i32, end: i32) -> i32 {
    // Run the content bytes cs[start, end): read operands, then execute each
    // operator. The caller's lexer position, graphics-state floor and marked-
    // content floor are kept and restored, so a form can run inside an operator.
    let oldpos: i32 = crate::port::cells_at(cx, C_POS);
    let oldend: i32 = crate::port::cells_at(cx, C_END);
    let oldgs: i32 = crate::port::cells_at(cx, C_GSBASE);
    let oldmcb: i32 = crate::port::cells_at(cx, C_MCBASE);
    let oldover: i32 = crate::port::cells_at(cx, C_MCOVER);
    let oldtop: i32 = crate::port::cells_at(cx, C_MCTOP);
    let mut r: i32 = 1;
    let mut opc: i32 = 0;
    let mut nop: i32 = 0;
    let mut ops: i32 = 0;
    crate::port::cells_set(cx, C_POS, start);
    crate::port::cells_set(cx, C_END, end);
    crate::port::cells_set(cx, C_GSBASE, crate::port::cells_at(cx, C_DEPTH));
    crate::port::cells_set(cx, C_MCBASE, crate::port::cells_at(cx, C_MCDEPTH));
    crate::port::cells_set(cx, C_MCOVER, 0);
    pc_ox_clear(cx, ox);
    while (r != 0) && (crate::port::cells_at(cx, C_ABORT) == 0) {
        r = pc_lex(cx, ox, cs);
        if r == 2 {
            ops = crate::port::cells_at(cx, C_OPS) + 1;
            crate::port::cells_set(cx, C_OPS, ops);
            if ops > crate::port::cells_at(cx, C_OPLIM) {
                crate::port::limit_breach(5, ops);
            }
            opc = crate::port::cells_at(cx, C_OP);
            nop = crate::port::cells_at(cx, C_OXN);
            pc_op(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pa, im, pts, gx, opc, nop);
            pc_ox_clear(cx, ox);
        }
    }
    // What the stream left open: spans, graphics states.
    while crate::port::cells_at(cx, C_MCDEPTH) > crate::port::cells_at(cx, C_MCBASE) {
        pc_warn_set(cx, W_MC);
        pc_mc_pop(cx, mk, gl, 1);
    }
    while crate::port::cells_at(cx, C_DEPTH) > crate::port::cells_at(cx, C_GSBASE) {
        crate::port::cells_set(cx, C_DEPTH, crate::port::cells_at(cx, C_DEPTH) - 1);
    }
    crate::port::cells_set(cx, C_MCTOP, oldtop);
    crate::port::cells_set(cx, C_CUROCG, mk_ocg_of(mk, oldtop));
    crate::port::cells_set(cx, C_MCOVER, oldover);
    crate::port::cells_set(cx, C_MCBASE, oldmcb);
    crate::port::cells_set(cx, C_GSBASE, oldgs);
    crate::port::cells_set(cx, C_POS, oldpos);
    crate::port::cells_set(cx, C_END, oldend);
    return 0;
}
pub(crate) const WORD_GAP_PM: i32 = 160;
pub(crate) const WORD_BACK_PM: i32 = 400;
pub(crate) const OFFSET_PM: i32 = 450;
pub(crate) const LINE_BACK_PM: i32 = 600;
pub(crate) const LINE_GAP_PM: i32 = 2000;
pub(crate) fn pc_axis(rot: i32) -> i32 {
    // The writing axis a rotation is within three degrees of, else -1 (a glyph run
    // at another angle is measured along its own direction, `pc-rot-gap`).
    let a: i32 = ((rot + 4500) / 9000) % 4;
    let mut d: i32 = rot - (a * 9000);
    if d < 0 {
        d = 0 - d;
    }
    if d > 18000 {
        d = 36000 - d;
    }
    if d <= 300 {
        return a;
    }
    return -1;
}
pub(crate) fn pc_offset(gl: &mut crate::port::Cells, j: i32, axis: i32) -> i32 {
    // Where glyph j's baseline is across its writing axis, in centipoints.
    if axis == 1 {
        return gl_get(gl, j, ch_x1());
    }
    if axis == 3 {
        return gl_get(gl, j, ch_x0());
    }
    return gl_get(gl, j, gf_by0());
}
pub(crate) fn pc_gap(gl: &mut crate::port::Cells, p: i32, g: i32, axis: i32) -> i32 {
    // The space along the axis between glyph p and the glyph g after it
    // (negative when they overlap or g is before p).
    if axis == 0 {
        return gl_get(gl, g, ch_x0()) - gl_get(gl, p, ch_x1());
    }
    if axis == 2 {
        return gl_get(gl, p, ch_x0()) - gl_get(gl, g, ch_x1());
    }
    if axis == 1 {
        return gl_get(gl, p, ch_y0()) - gl_get(gl, g, ch_y1());
    }
    return gl_get(gl, g, ch_y0()) - gl_get(gl, p, ch_y1());
}
pub(crate) fn pc_rot_gap(gl: &mut crate::port::Cells, p: i32, g: i32, size: i32) -> i32 {
    // For text at an arbitrary angle: the distance between glyph p's centre and
    // glyph g's, along the writing direction, less 60 percent of the size (the
    // two half-advances of adjacent letters), so it reads as `pc-gap` does.
    let rot: i32 = gl_get(gl, p, gf_rot());
    let ux: i64 = fx_cos(rot);
    let uy: i64 = (0 as i64) - fx_sin(rot);
    let dx2: i32 = (gl_get(gl, g, ch_x0()) + gl_get(gl, g, ch_x1())) - (gl_get(gl, p, ch_x0()) + gl_get(gl, p, ch_x1()));
    let dy2: i32 = (gl_get(gl, g, ch_y0()) + gl_get(gl, g, ch_y1())) - (gl_get(gl, p, ch_y0()) + gl_get(gl, p, ch_y1()));
    let al2: i64 = (fx_mul(fx_of_int(dx2), ux)).wrapping_add(fx_mul(fx_of_int(dy2), uy));
    return fx_round(al2 / (2 as i64)) - ((size * 600) / 1000);
}
pub(crate) fn pc_rot_off(gl: &mut crate::port::Cells, p: i32, g: i32) -> i32 {
    // The distance between the two glyphs' centres across the writing direction.
    let rot: i32 = gl_get(gl, p, gf_rot());
    let sn: i64 = fx_sin(rot);
    let cs: i64 = fx_cos(rot);
    let dx2: i32 = (gl_get(gl, g, ch_x0()) + gl_get(gl, g, ch_x1())) - (gl_get(gl, p, ch_x0()) + gl_get(gl, p, ch_x1()));
    let dy2: i32 = (gl_get(gl, g, ch_y0()) + gl_get(gl, g, ch_y1())) - (gl_get(gl, p, ch_y0()) + gl_get(gl, p, ch_y1()));
    let pe: i32 = fx_round((fx_mul(fx_of_int(dx2), sn)).wrapping_add(fx_mul(fx_of_int(dy2), cs)) / (2 as i64));
    if pe < 0 {
        return 0 - pe;
    }
    return pe;
}
pub(crate) fn pc_pair_gap(gl: &mut crate::port::Cells, p: i32, g: i32, axis: i32, size: i32) -> i32 {
    if axis < 0 {
        return pc_rot_gap(gl, p, g, size);
    }
    return pc_gap(gl, p, g, axis);
}
pub(crate) fn pc_pair_off(gl: &mut crate::port::Cells, p: i32, g: i32, axis: i32) -> i32 {
    // How far glyph g's baseline is from glyph p's, across the writing axis.
    if axis < 0 {
        return pc_rot_off(gl, p, g);
    }
    let d: i32 = pc_offset(gl, p, axis) - pc_offset(gl, g, axis);
    if d < 0 {
        return 0 - d;
    }
    return d;
}
pub(crate) fn pc_space_cp(cp: i32) -> i32 {
    // 1 for a code point that separates words: the spaces (U+0020, U+00A0,
    // U+1680, U+2000..200A, U+202F, U+205F, U+3000) and the tab.
    if (cp == 32) || ((cp == 160) || ((cp == 9) || ((cp == 5760) || ((cp == 8239) || ((cp == 8287) || (cp == 12288)))))) {
        return 1;
    }
    if (cp >= 8192) && (cp <= 8202) {
        return 1;
    }
    return 0;
}
pub(crate) fn pc_cl(v: i32) -> i32 {
    // Clamp a distance to +-1,000,000 centipoints so a per-mille product fits an I32.
    if v > 1000000 {
        return 1000000;
    }
    if v < -1000000 {
        return -1000000;
    }
    return v;
}
pub(crate) fn pc_rot_same(r1: i32, r2: i32) -> i32 {
    // 1 when two rotations (centi-degrees) agree to half a degree.
    let mut d: i32 = r1 - r2;
    if d < 0 {
        d = 0 - d;
    }
    if d > 18000 {
        d = 36000 - d;
    }
    if d <= 50 {
        return 1;
    }
    return 0;
}
pub(crate) fn pc_hidden_mode(mode: i32) -> i32 {
    // 1 for the invisible render modes, 3 and 7.
    if (mode == 3) || (mode == 7) {
        return 1;
    }
    return 0;
}
pub(crate) fn pc_continues(gl: &mut crate::port::Cells, p: i32, g: i32) -> i32 {
    // 1 when glyph g continues the word glyph p is in: the same rotation, on the
    // same baseline (to 45 percent of the size: sub- and superscripts stay), and
    // the gap along the axis neither a word space nor a step back.
    let rot: i32 = gl_get(gl, p, gf_rot());
    let axis: i32 = pc_axis(rot);
    let size: i32 = gl_get(gl, g, gf_size());
    let sizep: i32 = gl_get(gl, p, gf_size());
    let mut sz: i32 = size;
    let mut gap: i32 = 0;
    let mut off: i32 = 0;
    if pc_rot_same(rot, gl_get(gl, g, gf_rot())) == 0 {
        return 0;
    }
    // A word is one thing to see: a glyph of another visibility, or one that is hidden (mode 3, 7) where the other
    // is not, starts a new word (P3.6).
    if gl_get(gl, p, gf_vis()) != gl_get(gl, g, gf_vis()) {
        return 0;
    }
    if pc_hidden_mode(gl_get(gl, p, gf_mode())) != pc_hidden_mode(gl_get(gl, g, gf_mode())) {
        return 0;
    }
    if sizep > sz {
        sz = sizep;
    }
    if sz > 200000 {
        sz = 200000;
    }
    if sz < (0 - 200000) {
        sz = 0 - 200000;
    }
    off = pc_cl(pc_pair_off(gl, p, g, axis));
    if (off * 1000) > (sz * OFFSET_PM) {
        return 0;
    }
    gap = pc_cl(pc_pair_gap(gl, p, g, axis, sz));
    if (gap * 1000) > (sz * WORD_GAP_PM) {
        return 0;
    }
    if (gap * 1000) < (0 - (sz * WORD_BACK_PM)) {
        return 0;
    }
    return 1;
}
pub(crate) fn pc_gcls(gl: &mut crate::port::Cells, j: i32) -> i32 {
    // 1 when glyph j stands for a strong right-to-left LETTER (Hebrew, Arabic, Syriac, ...: the Unicode class R or
    // AL), 2 for a strong left-to-right letter, else 0. Letters decide the direction of a word and of a line (D162);
    // a digit, a separator or a mark does not.
    return bd_strong(gl_get(gl, j, ch_cp()));
}
pub(crate) fn pc_glyph_out(mut et: &mut crate::port::Cells, gl: &mut crate::port::Cells, j: i32, lvl: i32) -> i32 {
    // Append glyph j's text (every code point it stands for, or U+FFFD) to the evidence text. At bidi level 1
    // (lvl, L4) a text of ONE code point whose character is mirrored (a bracket) is the mirror: the glyph on the
    // page was drawn as the mirror image of the character it stands for.
    let ts: i32 = gl_get(gl, j, ch_tstart());
    let tl: i32 = gl_get(gl, j, ch_tlen());
    let mut cp: i32 = gl_get(gl, j, ch_cp());
    let mut k: i32 = 0;
    let mut cpv: i32 = 0;
    if (ts >= 0) && (tl > 0) {
        while k < tl {
            cpv = crate::port::cells_at(et, ts + k);
            if (lvl == 1) && (tl == 1) {
                cpv = bd_mirror(cpv);
            }
            etx_append_cp(et, cpv);
            k += 1;
        }
        return 0;
    }
    if cp >= 0 {
        if lvl == 1 {
            cp = bd_mirror(cp);
        }
        etx_append_cp(et, cp);
    } else {
        etx_append_cp(et, 65533);
    }
    return 0;
}
pub(crate) fn pc_bidi_text(mut et: &mut crate::port::Cells, gl: &mut crate::port::Cells, gfst: i32, glst: i32) -> i32 {
    // Append the text of glyphs [gfst, glst], which were SHOWN left to right, in LOGICAL order of a right-to-left
    // paragraph (`emon.bidi`, D162): the order the Bidirectional Algorithm would display them in. It is written
    // where the arena ended, moved down over the scratch the algorithm used, and the index it starts at is the
    // answer. (The scratch is the arena's own tail: the algorithm owns no memory.)
    let n: i32 = (glst - gfst) + 1;
    let b: i32 = crate::port::cells_len(et);
    let mut j: i32 = 0;
    let mut o: i32 = 0;
    let mut e: i32 = 0;
    let mut i: i32 = 0;
    let mut lv: i32 = 0;
    let mut k: i32 = 0;
    while j < n {
        crate::port::cells_push(et, gl_get(gl, gfst + j, ch_cp()));
        j += 1;
    }
    o = bd_order_of(et, b, n);
    e = crate::port::cells_len(et);
    j = 0;
    while j < n {
        i = crate::port::cells_at(et, o + j);
        lv = crate::port::cells_at(et, (o - n) + i);
        pc_glyph_out(et, gl, gfst + i, lv);
        j += 1;
    }
    k = 0;
    while k < (crate::port::cells_len(et) - e) {
        crate::port::cells_set(et, b + k, crate::port::cells_at(et, e + k));
        k += 1;
    }
    crate::port::cells_drop(et, b + (crate::port::cells_len(et) - e));
    return b;
}
pub(crate) fn pc_emit_word(mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut wd: &mut crate::port::Cells, mut fnt: &mut crate::port::Cells, page: i32, gfst: i32, glst: i32, wbk: i32) -> i32 {
    // Record glyphs [gfst, glst] as a word: the union of their boxes, their text, the
    // dominant font and size of the first, and `hidden-text` as its source when every
    // glyph is render mode 3. A right-to-left word whose glyphs run left to right on the
    // page (visual order, as Skia and most producers write them) has its TEXT written in
    // logical order by the Bidirectional Algorithm (`pc-bidi-text`, D162): numbers and their separators,
    // Latin runs, brackets and the neutrals between them as UAX #9 resolves them, not letter by letter. A word
    // with no letter to say so ("2026,") is put right once its line is known to be right to left
    // (`pc-word-fix`). The glyphs themselves stay as they were shown.
    let mut x0: i32 = gl_get(gl, gfst, ch_x0());
    let mut y0: i32 = gl_get(gl, gfst, ch_y0());
    let mut x1: i32 = gl_get(gl, gfst, ch_x1());
    let mut y1: i32 = gl_get(gl, gfst, ch_y1());
    let mut j: i32 = gfst;
    let mut tstart: i32 = -1;
    let mut visible: i32 = 0;
    let mut nr: i32 = 0;
    let mut nl: i32 = 0;
    let mut cl: i32 = 0;
    let mut rtlw: i32 = 0;
    while j <= glst {
        if gl_get(gl, j, ch_x0()) < x0 {
            x0 = gl_get(gl, j, ch_x0());
        }
        if gl_get(gl, j, ch_y0()) < y0 {
            y0 = gl_get(gl, j, ch_y0());
        }
        if gl_get(gl, j, ch_x1()) > x1 {
            x1 = gl_get(gl, j, ch_x1());
        }
        if gl_get(gl, j, ch_y1()) > y1 {
            y1 = gl_get(gl, j, ch_y1());
        }
        if (gl_get(gl, j, gf_mode()) != 3) && (gl_get(gl, j, gf_mode()) != 7) {
            visible = 1;
        }
        cl = pc_gcls(gl, j);
        if cl == 1 {
            nr += 1;
        }
        if cl == 2 {
            nl += 1;
        }
        j += 1;
    }
    if (nr > nl) && (glst > gfst) {
        if pc_axis(gl_get(gl, gfst, gf_rot())) == 0 {
            if gl_get(gl, glst, ch_x0()) >= gl_get(gl, gfst, ch_x0()) {
                rtlw = 1;
            }
        }
    }
    tstart = crate::port::cells_len(et);
    if rtlw == 0 {
        j = gfst;
        while j <= glst {
            pc_glyph_out(et, gl, j, 2);
            j += 1;
        }
    } else {
        tstart = pc_bidi_text(et, gl, gfst, glst);
    }
    let w: i32 = wd_new(wd, page, x0, y0, x1, y1, gl_get(gl, gfst, gf_bx0()), gl_get(gl, gfst, gf_by0()), gl_get(gl, glst, gf_bx1()), gl_get(gl, glst, gf_by1()), gl_get(gl, gfst, gf_rot()), 0, tstart, crate::port::cells_len(et) - tstart, -1, -1, -1);
    let fo: i32 = gl_get(gl, gfst, gf_font());
    if rtlw == 1 {
        wd_set(wd, w, hd_dir(), ld_rtl());
    }
    wd_set(wd, w, wf_gfirst(), gfst);
    wd_set(wd, w, wf_gcount(), (glst - gfst) + 1);
    wd_set(wd, w, wf_font(), fo);
    wd_set(wd, w, wf_size(), gl_get(gl, gfst, gf_size()));
    if (fo >= 0) && (fo < fo_count(fnt)) {
        wd_set(wd, w, wf_style(), fo_get(fnt, fo, fnf_style()));
    }
    wd_set(wd, w, wf_wbreak(), wbk);
    if visible == 0 {
        wd_set(wd, w, wf_src(), sr_hidden_text());
    }
    j = gfst;
    while j <= glst {
        gl_set(gl, j, ch_word(), w);
        j += 1;
    }
    return w;
}
pub(crate) fn pc_swap_rows(mut wd: &mut crate::port::Cells, i: i32, j: i32) -> i32 {
    let mut k: i32 = 0;
    let mut u: i32 = 0;
    let mut v: i32 = 0;
    while k < 24 {
        u = crate::port::cells_at(wd, (i * 24) + k);
        v = crate::port::cells_at(wd, (j * 24) + k);
        crate::port::cells_set(wd, (i * 24) + k, v);
        crate::port::cells_set(wd, (j * 24) + k, u);
        k += 1;
    }
    return 0;
}
pub(crate) fn pc_rev_rows(mut wd: &mut crate::port::Cells, a: i32, b: i32) -> i32 {
    let mut i: i32 = a;
    let mut j: i32 = b;
    while i < j {
        pc_swap_rows(wd, i, j);
        i += 1;
        j -= 1;
    }
    return 0;
}
pub(crate) fn pc_wcls(gl: &mut crate::port::Cells, wd: &mut crate::port::Cells, w: i32) -> i32 {
    // What a word is to the order of the words of a right-to-left line: 1 when it has a right-to-left letter,
    // 2 when it has a left-to-right letter and no right-to-left one, 3 when it is only numbers (and what goes
    // with them), 0 when it is only neutrals (a dash, a bullet).
    let g0: i32 = wd_get(wd, w, wf_gfirst());
    let gn: i32 = wd_get(wd, w, wf_gcount());
    let mut j: i32 = 0;
    let mut nr: i32 = 0;
    let mut nl: i32 = 0;
    let mut nn: i32 = 0;
    let mut cl: i32 = 0;
    while j < gn {
        cl = pc_gcls(gl, g0 + j);
        if cl == 1 {
            nr += 1;
        }
        if cl == 2 {
            nl += 1;
        }
        cl = bd_class(gl_get(gl, g0 + j, ch_cp()));
        if (cl == 3) || (cl == 4) {
            nn += 1;
        }
        j += 1;
    }
    if nr > 0 {
        return 1;
    }
    if nl > 0 {
        return 2;
    }
    if nn > 0 {
        return 3;
    }
    return 0;
}
pub(crate) fn pc_word_fix(gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, wd: &mut crate::port::Cells, w: i32) -> i32 {
    // A word of a right-to-left line that `pc-emit-word` left in the order it was shown, because nothing in it
    // said it was right to left ("2026,", "50%", "(1)", "ROI-" before a Hebrew letter): when its glyphs run
    // left to right on the page they are in visual order, so its text is put in logical order, as a word that
    // says so is. Done in place: the same code points, in the order the algorithm gives; nothing moves if the
    // order does not change. Answers 1 when it changed the text.
    let g0: i32 = wd_get(wd, w, wf_gfirst());
    let gn: i32 = wd_get(wd, w, wf_gcount());
    let ts: i32 = wd_get(wd, w, hd_tstart());
    let tl: i32 = wd_get(wd, w, hd_tlen());
    let b: i32 = crate::port::cells_len(et);
    let mut j: i32 = 0;
    let mut o: i32 = 0;
    let mut e: i32 = 0;
    let mut i: i32 = 0;
    let mut lv: i32 = 0;
    let mut changed: i32 = 0;
    if gn < 2 {
        return 0;
    }
    if wd_get(wd, w, hd_dir()) == ld_rtl() {
        return 0;
    }
    if pc_axis(gl_get(gl, g0, gf_rot())) != 0 {
        return 0;
    }
    if gl_get(gl, g0 + (gn - 1), ch_x0()) < gl_get(gl, g0, ch_x0()) {
        return 0;
    }
    while j < gn {
        crate::port::cells_push(et, gl_get(gl, g0 + j, ch_cp()));
        j += 1;
    }
    o = bd_order_of(et, b, gn);
    j = 0;
    while j < gn {
        i = crate::port::cells_at(et, o + j);
        lv = crate::port::cells_at(et, (o - gn) + i);
        if (i != j) || (lv == 1) {
            changed = 1;
        }
        j += 1;
    }
    if changed == 0 {
        crate::port::cells_drop(et, b);
        return 0;
    }
    e = crate::port::cells_len(et);
    j = 0;
    while j < gn {
        i = crate::port::cells_at(et, o + j);
        lv = crate::port::cells_at(et, (o - gn) + i);
        pc_glyph_out(et, gl, g0 + i, lv);
        j += 1;
    }
    if (crate::port::cells_len(et) - e) != tl {
        crate::port::cells_drop(et, b);
        return 0;
    }
    j = 0;
    while j < tl {
        crate::port::cells_set(et, ts + j, crate::port::cells_at(et, e + j));
        j += 1;
    }
    crate::port::cells_drop(et, b);
    return 1;
}
pub(crate) fn pc_line_bidi(mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut wd: &mut crate::port::Cells, mut ln: &mut crate::port::Cells, lidx: i32, wfst: i32, wlst: i32) -> i32 {
    // Line lidx holds words [wfst, wlst]. When more of its letters are right-to-left than left-to-right
    // it is a right-to-left line (`ld-rtl`). Its words that no letter put in logical order are put in it
    // (`pc-word-fix`); if the words run left to right on the page, their ORDER is made logical: reversed,
    // with each group of words that make one left-to-right run (Latin words, and the numbers and neutrals
    // between them, W7 and N1) turned back; each word's glyphs are re-pointed at it and its gap is the
    // space to the word that follows it in that order.
    let mut w: i32 = wfst;
    let mut nr: i32 = 0;
    let mut nl: i32 = 0;
    let mut j: i32 = 0;
    let mut cl: i32 = 0;
    let mut a: i32 = 0;
    let mut z: i32 = 0;
    let mut s: i32 = 0;
    let mut hasl: i32 = 0;
    let mut rtl: i32 = 0;
    let mut g0: i32 = 0;
    let mut gn: i32 = 0;
    while w <= wlst {
        g0 = wd_get(wd, w, wf_gfirst());
        gn = wd_get(wd, w, wf_gcount());
        j = 0;
        while j < gn {
            cl = pc_gcls(gl, g0 + j);
            if cl == 1 {
                nr += 1;
            }
            if cl == 2 {
                nl += 1;
            }
            j += 1;
        }
        w += 1;
    }
    // A paragraph's direction is its own, not each line's: a short last line that is mostly Latin (a
    // product name, an acronym) after a right-to-left line is still right to left (UAX #9, P2 and P3 read
    // the paragraph, and the lines of one run on). So a line is right to left when its right-to-left
    // letters outnumber the left-to-right ones, or when the line before it (same page) is and this one has a
    // right-to-left letter or no left-to-right one (a number, a bullet).
    rtl = 0;
    if nr > nl {
        rtl = 1;
    }
    if (lidx > 0) && (rtl == 0) {
        if ln_get(ln, lidx - 1, lh_page()) == ln_get(ln, lidx, lh_page()) {
            if ln_get(ln, lidx - 1, lh_dir()) == ld_rtl() {
                if (nr > 0) || (nl == 0) {
                    rtl = 1;
                }
            }
        }
    }
    if rtl == 0 {
        return 0;
    }
    ln_set(ln, lidx, lh_dir(), ld_rtl());
    w = wfst;
    while w <= wlst {
        pc_word_fix(gl, et, wd, w);
        w += 1;
    }
    if pc_axis(gl_get(gl, wd_get(wd, wfst, wf_gfirst()), gf_rot())) != 0 {
        return 0;
    }
    if wd_get(wd, wlst, hd_x0()) < wd_get(wd, wfst, hd_x0()) {
        return 0;
    }
    if wfst == wlst {
        return 0;
    }
    pc_rev_rows(wd, wfst, wlst);
    // Now the rows are in logical order but for the left-to-right runs, which are backwards: a run is a
    // maximal stretch of words that are not right-to-left, holding at least one left-to-right word, less
    // the neutral-only words at its ends (they are between a left-to-right and a right-to-left word: N2).
    a = wfst;
    while a <= wlst {
        if pc_wcls(gl, wd, a) == 1 {
            a += 1;
        } else {
            z = a;
            while (z < wlst) && (pc_wcls(gl, wd, z + 1) != 1) {
                z += 1;
            }
            hasl = 0;
            s = a;
            while s <= z {
                if pc_wcls(gl, wd, s) == 2 {
                    hasl = 1;
                }
                s += 1;
            }
            if hasl == 1 {
                s = a;
                while pc_wcls(gl, wd, s) == 0 {
                    s += 1;
                }
                j = z;
                while pc_wcls(gl, wd, j) == 0 {
                    j -= 1;
                }
                pc_rev_rows(wd, s, j);
            }
            a = z + 1;
        }
    }
    w = wfst;
    while w <= wlst {
        g0 = wd_get(wd, w, wf_gfirst());
        gn = wd_get(wd, w, wf_gcount());
        j = 0;
        while j < gn {
            gl_set(gl, g0 + j, ch_word(), w);
            j += 1;
        }
        z = -1;
        if w < wlst {
            z = wd_get(wd, w, hd_x0()) - wd_get(wd, w + 1, hd_x1());
        }
        wd_set(wd, w, wf_gap(), z);
        w += 1;
    }
    return 0;
}
pub fn pc_group(mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut wd: &mut crate::port::Cells, mut ln: &mut crate::port::Cells, mut fnt: &mut crate::port::Cells, page: i32, g0: i32, w0: i32) -> i32 {
    // Group the glyphs from g0 on into words, and the words from w0 on into lines.
    let g1: i32 = gl_count(gl);
    let mut i: i32 = g0;
    let mut cur: i32 = -1;
    while i < g1 {
        if pc_space_cp(gl_get(gl, i, ch_cp())) == 1 {
            if cur >= 0 {
                pc_emit_word(gl, et, wd, fnt, page, cur, i - 1, wb_space());
                cur = -1;
            }
        } else {
            if cur >= 0 {
                if pc_continues(gl, i - 1, i) == 0 {
                    pc_emit_word(gl, et, wd, fnt, page, cur, i - 1, wb_gap());
                    cur = -1;
                }
            }
            if cur < 0 {
                cur = i;
            }
        }
        i += 1;
    }
    if cur >= 0 {
        pc_emit_word(gl, et, wd, fnt, page, cur, g1 - 1, wb_line_end());
        cur = -1;
    }
    // Lines: consecutive words on one baseline, in order.
    let nw: i32 = wd_count(wd);
    let mut j: i32 = w0;
    let mut lfirst: i32 = -1;
    let mut prev: i32 = -1;
    let mut lnx: i32 = 0;
    let mut x0: i32 = 0;
    let mut y0: i32 = 0;
    let mut x1: i32 = 0;
    let mut y1: i32 = 0;
    let mut gf0: i32 = 0;
    let mut gfp: i32 = 0;
    let mut glast: i32 = 0;
    let mut axis: i32 = 0;
    let mut joins: i32 = 0;
    let mut gap: i32 = 0;
    let mut sz: i32 = 0;
    let mut ord: i32 = 0;
    let mut off: i32 = 0;
    while j <= nw {
        joins = 0;
        if (j < nw) && (prev >= 0) {
            gf0 = wd_get(wd, j, wf_gfirst());
            gfp = wd_get(wd, prev, wf_gfirst());
            axis = pc_axis(gl_get(gl, gfp, gf_rot()));
            if pc_rot_same(gl_get(gl, gfp, gf_rot()), gl_get(gl, gf0, gf_rot())) == 1 {
                sz = gl_get(gl, gf0, gf_size());
                if gl_get(gl, gfp, gf_size()) > sz {
                    sz = gl_get(gl, gfp, gf_size());
                }
                if sz > 200000 {
                    sz = 200000;
                }
                if sz < (0 - 200000) {
                    sz = 0 - 200000;
                }
                glast = (wd_get(wd, prev, wf_gfirst()) + wd_get(wd, prev, wf_gcount())) - 1;
                off = pc_cl(pc_pair_off(gl, glast, gf0, axis));
                // The gap is between the previous word's LAST glyph and this word's first.
                gap = pc_cl(pc_pair_gap(gl, glast, gf0, axis, sz));
                if (off * 1000) <= (sz * OFFSET_PM) {
                    if (gap * 1000) >= (0 - (sz * LINE_BACK_PM)) {
                        if (gap * 1000) <= (sz * LINE_GAP_PM) {
                            joins = 1;
                        }
                    }
                }
            }
        }
        if joins == 1 {
            wd_set(wd, prev, wf_gap(), gap);
            prev = j;
        } else {
            // The line so far ends at `prev`: record it, then start a new one at j.
            if lfirst >= 0 {
                x0 = wd_get(wd, lfirst, hd_x0());
                y0 = wd_get(wd, lfirst, hd_y0());
                x1 = wd_get(wd, lfirst, hd_x1());
                y1 = wd_get(wd, lfirst, hd_y1());
                lnx = lfirst;
                while lnx <= prev {
                    if wd_get(wd, lnx, hd_x0()) < x0 {
                        x0 = wd_get(wd, lnx, hd_x0());
                    }
                    if wd_get(wd, lnx, hd_y0()) < y0 {
                        y0 = wd_get(wd, lnx, hd_y0());
                    }
                    if wd_get(wd, lnx, hd_x1()) > x1 {
                        x1 = wd_get(wd, lnx, hd_x1());
                    }
                    if wd_get(wd, lnx, hd_y1()) > y1 {
                        y1 = wd_get(wd, lnx, hd_y1());
                    }
                    lnx += 1;
                }
                gfp = wd_get(wd, lfirst, wf_gfirst());
                axis = pc_axis(gl_get(gl, gfp, gf_rot()));
                ord = wd_get(wd, lfirst, wf_gfirst());
                lnx = lfirst;
                while lnx <= prev {
                    if wd_get(wd, lnx, wf_gfirst()) < ord {
                        ord = wd_get(wd, lnx, wf_gfirst());
                    }
                    lnx += 1;
                }
                // The baseline runs from the first word's start to the last word's end, in the
                // order the words were SHOWN (the bidi step below re-orders the rows, not the page).
                lnx = ln_new(ln, page, x0, y0, x1, y1, wd_get(wd, lfirst, hd_bx0()), wd_get(wd, lfirst, hd_by0()), wd_get(wd, prev, hd_bx1()), wd_get(wd, prev, hd_by1()), gl_get(gl, gfp, gf_rot()), 0, lfirst, (prev - lfirst) + 1);
                ln_set(ln, lnx, lf_order(), ord);
                pc_line_bidi(gl, et, wd, ln, lnx, lfirst, prev);
                wd_set(wd, prev, wf_wbreak(), wb_line_end());
                gfp = lfirst;
                while gfp <= prev {
                    wd_set(wd, gfp, hd_line(), lnx);
                    gfp += 1;
                }
            }
            lfirst = j;
            prev = j;
        }
        j += 1;
    }
    return 0;
}
pub(crate) fn pc_begin_page(mut cx: &mut crate::port::Cells, page: i32) -> i32 {
    // Reset everything a page owns; the fonts (the document's) stay.
    crate::port::cells_set(cx, C_PAGE, page);
    crate::port::cells_set(cx, C_WARN, 0);
    crate::port::cells_set(cx, C_OPS, 0);
    crate::port::cells_set(cx, C_ABORT, 0);
    crate::port::cells_set(cx, C_POS, 0);
    crate::port::cells_set(cx, C_END, 0);
    crate::port::cells_set(cx, C_OXN, 0);
    crate::port::cells_set(cx, C_CDEPTH, 0);
    crate::port::cells_set(cx, C_OP, 0);
    crate::port::cells_set(cx, C_RES, 0);
    crate::port::cells_set(cx, C_SLOT, -1);
    crate::port::cells_set(cx, C_DEPTH, 0);
    crate::port::cells_set(cx, C_FDEPTH, 0);
    crate::port::cells_set(cx, C_STM, 0);
    crate::port::cells_set(cx, C_MCTOP, -1);
    crate::port::cells_set(cx, C_MCDEPTH, 0);
    crate::port::cells_set(cx, C_MCBASE, 0);
    crate::port::cells_set(cx, C_MCOVER, 0);
    crate::port::cells_set(cx, C_CUROCG, -1);
    crate::port::cells_set(cx, C_Z, 0);
    crate::port::cells_set(cx, C_INTEXT, 0);
    crate::port::cells_set(cx, C_CLIPP, 0);
    crate::port::cells_set(cx, C_TCN, 0);
    crate::port::cells_set(cx, C_NPATH, 0);
    crate::port::cells_set(cx, C_NIMG, 0);
    crate::port::cells_set(cx, C_GSBASE, 0);
    mx_ident(cx, C_TM);
    mx_ident(cx, C_TLM);
    mx_ident(cx, C_M);
    return 0;
}
pub fn pc_page(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut ox: &mut crate::port::Cells, mut cs: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut mk: &mut crate::port::Cells, mut fnt: &mut crate::port::Cells, pg: &mut crate::port::Cells, pi: i32, page: i32, mut wd: &mut crate::port::Cells, mut ln: &mut crate::port::Cells, mut pa: &mut crate::port::Cells, mut im: &mut crate::port::Cells, mut pts: &mut crate::port::Cells, mut gx: &mut crate::port::Cells) -> i32 {
    // Interpret page index pi of the page table pg (page number `page`, 1-based, is
    // what the evidence records): its content streams, then the words and lines.
    // Answers 0, or 7 (`need-bytes`) when the source missed: then nothing written is
    // to be used and the caller re-runs on a fresh view (D075).
    let con: i32 = pd_pg_contents(pg, pi);
    let g0: i32 = gl_count(gl);
    let w0: i32 = wd_count(wd);
    let p0: i32 = pa_count(pa);
    let i0: i32 = im_count(im);
    let rot: i32 = pd_pg_rotate(pg, pi);
    let cw: i32 = pd_pg_crop(pg, pi, 2) - pd_pg_crop(pg, pi, 0);
    let ch: i32 = pd_pg_crop(pg, pi, 3) - pd_pg_crop(pg, pi, 1);
    let mut el: i32 = 0;
    let mut eh: i32 = 0;
    let mut endcs: i32 = 0;
    pc_begin_page(cx, page);
    crate::port::cells_set(cx, C_PTS0, pt_count(pts));
    pc_base_matrix(cx, pd_pg_crop(pg, pi, 0), pd_pg_crop(pg, pi, 1), pd_pg_crop(pg, pi, 2), pd_pg_crop(pg, pi, 3), pd_pg_rotate(pg, pi));
    pc_gs_reset(cx);
    gx_page(gx);
    gx_oc_read(src, ar, dc, a, b, st, gx);
    if (rot == 90) || (rot == 270) {
        crate::port::cells_set(cx, C_PW, ch);
        crate::port::cells_set(cx, C_PH, cw);
    } else {
        crate::port::cells_set(cx, C_PW, cw);
        crate::port::cells_set(cx, C_PH, ch);
    }
    pc_path_reset(cx, pts);
    crate::port::cells_set(cx, C_RES, pd_pg_resources(pg, pi));
    crate::port::cells_drop(cs, 0);
    if con != 0 {
        if pl_kind_of(ar, con) == 8 {
            pc_append_stream(src, ar, dc, a, b, st, cx, out, cs, con);
        }
        if pl_kind_of(ar, con) == 6 {
            el = pl_first(ar, con);
            while (el != 0) && (crate::port::cells_at(cx, C_ABORT) == 0) {
                eh = pd_resolve(src, ar, dc, a, b, st, el);
                if ps_missed(src) {
                    crate::port::cells_set(cx, C_ABORT, 1);
                }
                if (eh != 0) && (pl_kind_of(ar, eh) == 8) {
                    pc_append_stream(src, ar, dc, a, b, st, cx, out, cs, eh);
                }
                el = pl_next(ar, el);
            }
        }
    }
    if crate::port::cells_at(cx, C_ABORT) == 1 {
        return 7;
    }
    endcs = crate::port::cells_len(cs);
    pc_run(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pa, im, pts, gx, 0, endcs);
    if crate::port::cells_at(cx, C_ABORT) == 1 {
        return 7;
    }
    if ps_missed(src) {
        return 7;
    }
    // The path in progress when the page ended never painted: its points are dropped.
    crate::port::cells_drop(pts, crate::port::cells_at(cx, C_PPTS) * 3);
    pv_page(gl, mk, pa, im, crate::port::cells_at(cx, C_PW), crate::port::cells_at(cx, C_PH), g0, p0, i0);
    pc_group(gl, et, wd, ln, fnt, page, g0, w0);
    return 0;
}
pub fn pc_document(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut ox: &mut crate::port::Cells, mut cs: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut mk: &mut crate::port::Cells, mut fnt: &mut crate::port::Cells, mut pg: &mut crate::port::Cells, mut wd: &mut crate::port::Cells, mut ln: &mut crate::port::Cells, mut pa: &mut crate::port::Cells, mut im: &mut crate::port::Cells, mut pts: &mut crate::port::Cells, mut gx: &mut crate::port::Cells) -> i32 {
    // Every page of an opened document (`pd-open` has answered 0): clears `cx`,
    // then `pc-page` for each page. Answers 0, or 7 when the source missed.
    pc_init(cx, ox);
    crate::port::cells_drop(fnt, 0);
    crate::port::cells_drop(gx, 0);
    let n: i32 = pd_pages(src, ar, dc, a, b, st, pg);
    let mut i: i32 = 0;
    let mut status: i32 = 0;
    if n < 0 {
        return 7;
    }
    while i < n {
        status = pc_page(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, i, i + 1, wd, ln, pa, im, pts, gx);
        if status == 7 {
            return 7;
        }
        i += 1;
    }
    return 0;
}
